NAME = 'GerAlbrecht: German Albrecht Neues Testament und Psalmen'
BOOK = 'Matthew'

CHAPTERS = {
    1: {
        1: 'Dies ist das Buch der Geschichte Jesu Christi, des Sohnes Davids, des Sohnes Abrahams.',
        2: 'Abraham war der Vater Isaaks. Isaak war der Vater Jakobs. Jakob war der Vater Judas und seiner Brüder.',
        3: 'Juda war — durch Thamar — der Vater des Perez und Serah. Perez war der Vater Hezrons. Hezron war der Vater Rams.',
        4: 'Ram war der Vater Aminadabs. Aminadab war der Vater Nahessons. Nahesson war der Vater Salmas.',
        5: 'Salma war — durch Rahab — der Vater des Boas. Boas war — durch Ruth — der Vater Obeds. Obed war der Vater Isais.',
        6: 'Isai war der Vater des Königs David. David war — durch Urias Witwe — der Vater Salomos.',
        7: 'Salomo war der Vater Rehabeams. Rehabeam war der Vater Abias. Abia war der Vater Asas.',
        8: 'Asa war der Vater Josafats. Josafat war der Vater Jorams. Joram war der Vater Usias.',
        9: 'Usia war der Vater Jotams. Jotam war der Vater des Ahas. Ahas war der Vater Hiskias.',
        10: 'Hiskia war der Vater Manasses. Manasse war der Vater Amons. Amon war der Vater Josias.',
        11: 'Josia wurde der Vater Jechonjas und seiner Brüder zur Zeit der Wegführung nach Babylon.',
        12: 'Nach der Wegführung nach Babylon wurde Jechonja der Vater Sealthiels. Sealthiel war der Vater Serubabels.',
        13: 'Serubabel war der Vater Abiuds. Abiud war der Vater Eljakims. Eljakim war der Vater Asors.',
        14: 'Asor war der Vater Zadoks. Zadoks war der Vater Achims. Achim war der Vater Eliuds.',
        15: 'Eliud war der Vater Eleasars. Eleasar war der Vater Matthans. Matthan war der Vater Jakobs.',
        16: 'Jakob war der Vater Josefs, des Mannes der Maria. Maria aber ist die Mutter jenes Jesus, der den Namen Christus trägt.',
        17: 'Alle Geschlechter von Abraham bis David betragen vierzehn. Auch von David bis zu der Wegfnhrung nach Babylon sind vierzehn Geschlechter. Ebenso sind vierzehn Geschlechter von der Wegfnhrung nach Babylon bis auf den Messias.',
        18: "Mit Christi Geburt verhielt es sich so: Als seine Mutter Maria mit Josef verlobt war, da zeigte sich's, noch ehe sie zusammenzogen, daß sie vom Heiligen Geist empfangen hatte.",
        19: 'Josef aber, ihr Verlobter, der ein frommer Mann war und sie nicht bloßstellen wollte, ging schon damit um, sich in aller Stille von ihr zu trennen.',
        20: 'Als er dies erwog, da erschien ihm im Traume ein Engel des Herrn und sprach zu ihm: "Josef, du Sohn Davids, scheue dich nicht, Maria, deine Verlobte, zu deiner Ehefrau zu machen! Denn was in ihr erzeugt ist, das stammt von dem Heiligen Geiste.',
        21: 'Und sie wird einen Sohn gebären, dem sollst du den Namen Jesus geben; denn er wird sein Volk erretten von ihren Sünden."',
        22: 'Dies alles ist geschehen, damit sich jenes Wort erfülle, das der Herr durch den Mund des Propheten gesprochen hat:',
        23: 'Siehe, die Jungfrau wird empfangen und einen Sohn gebären, und seinen Namen wird man nennen Immanuel, das heißt: mit uns ist Gott.',
        24: 'Als Josef von seinem Schlaf erwachte, tat er, wie ihm der Engel des Herrn befohlen hatte, und führte seine Verlobte als Eheweib heim.',
        25: 'Aber er verkehrte nicht mit ihr, bis sie einen Sohn geboren hatte. Dem gab er den Namen Jesus.',
    },
    2: {
        1: 'Als Jesus in den Tagen des Königs Herodes zu Bethlehem in Judäa geboren war, da trafen Sterndeuter aus dem Morgenlande in Jerusalem ein und fragten:',
        2: '"Wo ist der König der Juden? Er ist geboren; denn wir haben in den Strahlen der Morgendämmerung seinen Stern erscheinen sehn und sind hierher gekommen, um ihm zu huldigen."',
        3: 'Als dies dem König Herodes zu Ohren kam, erschrak er, und mit ihm entsetzte sich auch ganz Jerusalem.',
        4: 'Da berief er alle Hohenpriester und Schriftgelehrten des Volkes und legte ihnen die Frage vor: "Wo soll der Messias geboren werden?"',
        5: 'Sie antworteten ihm: "Zu Bethlehem in Judäa. Denn so steht geschrieben in den Worten des Propheten:',
        6: 'Und du, Bethlehem im Lande Juda, du bist durchaus nicht die geringste unter den Führerstädten. Denn aus dir soll mir ein Herrscher kommen, der wird als Hirte weiden mein Volk Israel."',
        7: 'Hierauf ließ Herodes die Sterndeuter in aller Stille zu sich rufen und sich von ihnen genau die Zeit angeben, wann der Stern zuerst erschienen sei.',
        8: 'Dann wies er sie nach Bethlehem und sprach: "Zieht hin und forscht mit Sorgfalt nach dem Kinde; und habt ihr es gefunden, so gebt mir Nachricht, damit ich auch komme und ihm huldige."',
        9: 'Als sie dies von dem Könige vernommen hatten, machten sie sich auf den Weg. Und sieh, der Stern, den sie im Frühaufgang gesehn, zog vor ihnen her, bis er stillstand über dem Hause, wo das Kindlein war.',
        10: 'Bei dem Anblick des Sternes wurden sie mit großer Freude erfüllt.',
        11: 'Sie traten in das Haus und sahen das Kind bei Maria, seiner Mutter. Da fielen sie vor ihm nieder und huldigten ihm. Dann öffneten sie ihre Schatzbehälter und brachten ihm Gold, Weihrauch und Myrrhen als Geschenke dar.',
        12: 'Im Traum erhielten sie die Weisung, nicht wieder zu Herodes zu gehn. Deshalb zogen sie auf einem andern Wege in ihr Heimatland zurück.',
        13: 'Als sie weggezogen waren, da erschien ein Engel des Herrn dem Josef im Träume und sprach zu ihm: "Auf, nimm das Kind und seine Mutter, flieh nach Ägypten und bleibe dort so lange, bis ich dir Nachricht gebe! Denn Herodes will das Kind in seine Gewalt bekommen, um es zu töten."',
        14: 'Da stand er auf und nahm noch in derselben Nacht das Kind und seine Mutter und machte sich auf den Weg nach Ägypten.',
        15: 'Dort blieb er bis zum Tode des Herodes. So erfüllte sich das Wort des Herrn durch den Propheten: Aus Ägypten hat ich meinen Sohn gerufen.',
        16: 'Als nun Herodes sah, daß ihn die Sterndeuter getäuscht hatten, ward er sehr zornig: er sandte Henker aus und ließ in Bethlehem und dem ganzen Umkreis dieses Ortes alle Knaben in dem Alter von zwei Jahren und darunter töten, nach dem Zeitpunkt, den er von den Sterndeutern genau erforscht hatte.',
        17: 'Damals erfüllte sich das Wort des Propheten Jeremia:',
        18: 'In Rama hat man ein Geschrei gehört, lautes Weinen und Klagen: Rahel weint um ihre Kinder und will sich nicht trösten lassen; denn sie sind dahin.',
        19: 'Als aber Herodes gestorben war, da erschien in Ägypten ein Engel des Herrn dem Josef im Traum',
        20: 'und sprach zu ihm: "Auf, nimm das Kind und seine Mutter und ziehe ins Land Israel! Denn die dem Kinde nach dem Leben trachteten, die sind nun tot."',
        21: 'Da stand er auf und nahm das Kind und seine Mutter und kam in das Land Israel.',
        22: 'Als er aber hörte, daß Archelaus an Stelle seines Vaters Herodes in Judäa herrschte, trug er Bedenken, sich dort niederzulassen; und nach einer göttlichen Weisung, die er im Träume empfing, zog er sich in die Landschaft Galiläa zurück.',
        23: 'Dort nahm er Wohnung in einer Stadt, mit Namen Nazaret, damit die Worte der Propheten in Erfüllung gingen. Denn er sollte ja den Namen Nazaräer tragen.',
    },
    3: {
        1: 'In jenen Tagen trat Johannes der Täufer auf und ließ in der Wüste Judäas den Ruf erschallen:',
        2: '"Ändert euern Sinn, denn das Königreich der Himmel ist nahe herbeigekommen!"',
        3: 'Er ist der Mann, vom dem der Prophet Jesaja gesprochen hat: In der Wüste ruft eine Stimme: "Bereitet dem Herrn den Weg, ebnet ihm die Pfade!"',
        4: 'Johannes aber trug ein Kleid von Kamelhaaren und um seine Hüften einen Ledergurt; und seine Nahrung waren Heuschrecken und wilder Honig.',
        5: 'Da gingen die Leute aus Jerusalem, aus ganz Judäa und aus der ganzen Gegend um den Jordan zu ihm hinaus,',
        6: 'ließen sich im Jordanflusse taufen und bekannten ihre Sünden.',
        7: 'Als er nun auch viele Pharisäer und Sadduzäer zu seiner Taufe kommen sah, sprach er zu ihnen: "Ihr Schlangenbrut! Wer hat euch denn gesagt, daß ihr dem kommenden Zorngericht entrinnen könnt?',
        8: 'So bringt den Frucht, wie sie der Sinnesänderung entspricht!',
        9: "Und laßt euch nur nicht beikommen, zu denken: 'Wir haben ja Abraham zum Vater.' Denn ich sage euch: Gott kann aus diesen Steinen hier dem Abraham Kinder entstehen lassen.",
        10: 'Schon liegt die Axt den Bäumen an der Wurzel; und jeder Baum, der nicht gute Frucht bringt, wird abgehauen und ins Feuer geworfen.',
        11: 'Ich taufe euch mit Wasser, damit ihr euern Sinn ändert. Der aber nach mir kommt, hat größere Gewalt als ich, und ich bin nicht wert, ihm seine Schuhe nachzutragen: der wird euch mit Heiligem Geiste und mit Feuer taufen.',
        12: 'Er hat schon die Wurfschaufel in der Hand und wird seine Tenne reinigen: seinen Weizen wird er in den Speicher sammeln; aber die Spreu wird er verbrennen mit einem Feuer, das niemand löschen kann."',
        13: 'Damals kam auch Jesus aus Galiläa an den Jordan zu Johannes, um sich von ihm taufen zu lassen.',
        14: 'Der aber suchte ihn davon abzubringen, indem er sprach: "Ich hätte es nötig, mich von dir taufen zu lassen, und du kommst zu mir?"',
        15: 'Doch Jesus antwortete ihm: "Laß mich nur! Denn so ziemt es uns, jede Vorschrift zu erfüllen." Da gab Johannes ihm nach.',
        16: 'In dem Augenblick aber, als Jesus nach seiner Taufe aus dem Wasser emporstieg, tat sich der Himmel über ihm auf, und er sah den Geist Gottes wie eine Taube niederschweben und auf sich kommen.',
        17: 'Und eine Stimme aus dem Himmel sprach: "Dies ist mein geliebter Sohn, den ich erkoren habe."',
    },
    4: {
        1: 'Dann ward Jesus vom Geist in die Wüste geführt, um von dem Teufel versucht zu werden.',
        2: 'Und als er vierzig Tage und vierzig Nächte gefastet hatte, empfand er zuletzt Hunger.',
        3: 'Da trat der Versucher zu ihm und sprach: "Bist du Gottes Sohn, so befiehl, daß sich diese Steine hier in Brot verwandeln."',
        4: 'Doch er antwortete: "Es steht geschrieben: Der Mensch wird nicht durch Brot allein am Leben erhalten, sondern durch alles, was ihm durch Gottes Allmachtswort bereitet wird."',
        5: 'Dann nahm ihn der Teufel mit sich in die heilige Stadt, stellte ihn auf das flachte Dach der Tempelhalle',
        6: 'und sprach zu ihm: "Bist du Gottes Sohn, so stürze dich hinab, denn es steht geschrieben: Er wird seinen Engeln deinetwegen Auftrag geben, und sie sollen dich auf den Händen tragen, daß du nicht mit deinem Fuß an einen Stein stoßest."',
        7: 'Jesus aber erwiderte ihm: "Anderseits steht auch geschrieben: Du sollst den Herrn, deinen Gott, nicht versuchen."',
        8: 'Weiter nahm ihn der Teufel mit sich auf einen sehr hohen Berg. Von dort aus zeigte er ihm alle Reiche der Welt mit ihrer Pracht',
        9: 'und sprach zu ihm: "Dies alles will ich dir geben, wenn du vor mir niederfällst und mir huldigst."',
        10: 'Da antwortete ihm Jesus: "Mir aus den Augen, Satan! Denn es steht geschrieben: Du sollst dem Herrn, deinem Gott, anbetend huldigen und ihn allein verehren."',
        11: 'Da verließ ihn der Teufel, und nun kamen Engel herbei und brachten ihm Speise.',
        12: 'Auf die Kunde, Johannes sei verhaftet worden, zog sich Jesus nach Galiläa zurück.',
        13: 'Er verließ Nazaret und nahm seine Wohnung in Kapernaum am See in dem Gebiet von Sebulon und Naphtali. —',
        14: 'So erfüllte sich der Ausspruch des Propheten Jesaja:',
        15: 'Das Land Sebulon und das Land Naphtali, das Gebiet nach dem Meere zu, die Gegend östlich vom Jordan, das heidnische Galiläa',
        16: '- das Volk, das im Finstern saß, hat ein großes Licht gesehn, und denen, die in des Todes Land und Schatten wohnten, hat ein Licht geleuchtet.',
        17: 'Seit der Zeit begann Jesus öffentlich zu lehren. Seine Botschaft lautete: "Ändert euern Sinn, denn das Königreich der Himmel ist nahe herbeigekommen!"',
        18: 'Als Jesus (eines Tages) an dem Ufer des Galiläischen Sees wandelte, erblickte er zwei Brüder: Simon, mit dem Beinamen Petrus, und seinen Bruder Andreas; die warfen ein Wurfnetz in den See, denn sie waren Fischer.',
        19: 'Und er sprach zu ihnen: "Kommt und folget mir, ich will euch zu Menschenfischern machen."',
        20: 'Da ließen sie sofort ihre Netze liegen und folgten ihm.',
        21: 'Als er dann weiterging, sah er ein anderes Brüderpaar: Jakobus, den Sohn des Zebedäus, und seinen Bruder Johannes; die brachten in ihrem Boote mit ihrem Vater Zebedäus ihre Hochseenetze in Ordnung. Und er berief sie.',
        22: 'Sogleich verließen sie das Boot und ihren Vater und folgten ihm.',
        23: 'Jesus zog umher in ganz Galiläa: er lehrte in ihren Versammlungshäusern, verkündigte die frohe Botschaft vom Königreiche und heilte allerlei Krankheiten und Gebrechen im Volke.',
        24: 'Die Kunde von ihm ging weiter und drang durch ganz Syrien. Da brachte man zu ihm alle, die an den verschiedenartigsten Gebrechen litten: von Schmerzen Geplagte, Besessene, Mondsüchtige, Gelähmte; und er heilte sie.',
        25: 'Es folgten ihm große Volksscharen aus Galiläa und dem Gebiete der Zehn Städte, aus Jerusalem und Judäa und aus der Gegend jenseits des Jordans.',
    },
    5: {
        1: 'Als er die Volksmenge sah, ging er auf die Bergeshöhe. Dort setzte er sich nieder, und seine Jünger traten zu ihm.',
        2: 'Da tat er seinen Mund auf und lehrte sie also:',
        3: '"Selig sind die Armen im Geist! Denn das Königreich der Himmel ist ihr Teil.',
        4: 'Selig sind die Trauernden! Denn sie sollen getröstet werden.',
        5: 'Selig sind die stillen Dulder! Denn ihr Erbteil soll die Erde sein.',
        6: 'Selig sind, die hungern und dürsten nach der Gerechtigkeit! Denn sie sollen gesättigt werden.',
        7: 'Selig sind die Barmherzigen! Denn ihnen soll Erbarmen widerfahren.',
        8: 'Selig sind, die reines Herzens sind! Denn sie sollen Gott schauen.',
        9: 'Selig sind die Friedenstifter! Denn sie sollen Söhne Gottes heißen.',
        10: 'Selig sind, die um Gerechtigkeit willen Verfolgung gelitten haben! Denn das Königreich der Himmel ist ihr Teil.',
        11: 'Selig seid ihr, wenn man euch schmähet und verfolgt und um meinetwillen lügnerisch allerlei Böses von euch redet.',
        12: 'Freuet euch darüber und jubelt, denn euer Lohn dafür ist groß im Himmel! Ebenso hat man ja die Propheten verfolgt, die vor euch lebten.',
        13: 'Ihr seid das Salz der Erde. Wird aber das Salz fade, womit soll man ihm die Salzkraft wiedergeben? Es hat dann weiter keinen Wert; man muß es wegwerfen und von den Leuten zertreten lassen.',
        14: 'Ihr seid das Licht der Welt. Eine Stadt, die auf einem Berge liegt, kann nicht verborgen bleiben.',
        15: 'Man zündet auch nicht eine Lampe an und setzt sie dann unter einen Scheffel; sondern man stellt sie auf den Leuchter; dann gibt sie allen Hausbewohnern Licht.',
        16: 'Ebenso soll euer Licht vor den Menschen leuchten, damit sie eure guten Werke sehen und euern Vater im Himmel preisen.',
        17: 'Denkt nicht, ich sei gekommen, um das Gesetz oder die Propheten aufzuheben! Ich bin nicht gekommen, um aufzuheben, sondern um zu erfüllen.',
        18: 'Wahrlich, ich sage euch: Eher können Himmel und Erde vergehn, als daß auch nur der kleinste Buchstabe oder ein einziger Strich vom Gesetz abhanden kommt, ohne daß alles erfüllt wird.',
        19: 'Wer darum eins von diesen Geboten, und sei es das geringste, aufhebt und so die Leute lehrt, der wird der Geringste heißen im Königreich der Himmel; wer es aber erfüllt und lehrt, der wird ein Großer heißen im Königreich der Himmel.',
        20: 'Denn ich versichere euch: Steht es bei euch mit der Gerechtigkeit nicht viel besser als bei den Schriftgelehrten und Pharisäern, so werdet ihr gewiß nicht eingehn ins Königreich der Himmel.',
        21: 'Ihr habt gehört, daß zu den Alten gesagt worden ist: Du sollst nicht morden! Wer aber einen Mord begeht, der soll dem Ortsgericht verfallen sein.',
        22: 'Ich aber sage euch: Wer seinem Bruder zürnt, der soll dem Ortsgericht verfallen; wer aber zu seinem Bruder mit Verachtung redet, der soll dem Hohen Rat verfallen; und wer das Scheltwort Narr gebraucht, der soll der Glut des Feuers verfallen.',
        23: 'Wenn du also deine Opfergabe schon zum Altar gebracht hast, und es fällt dir dort ein, daß dein Bruder gegen dich einen Grund zur Klage hat,',
        24: 'so laß dort deine Opfergabe vor dem Altar stehn und geh zunächst hin und söhne dich mit deinem Bruder aus; dann erst komm und bring dein Opfer dar!',
        25: 'Zeig dich beizeiten deinem Gläubiger entgegenkommend, solange du noch mit ihm auf dem Wege bist! Sonst könnte dich der Gläubiger vor den Richter bringen und der Richter dich dem Büttel übergeben, und man könnte dich ins Schuldgefängnis werfen.',
        26: 'Wahrlich, ich sage dir: Du kommst dort nicht eher heraus, als bis du den letzten Pfennig bezahlt hast.',
        27: 'Ihr habt gehört, daß gesagt worden ist: Du sollst nicht ehebrechen!',
        28: 'Ich aber sage euch: Wer ein Weib begehrlich anblickt, der hat schon in seinem Herzen Ehebruch mit ihr getrieben.',
        29: 'Wenn dich nun dein rechtes Auge zur Sünde verführt, so reiß es aus und wirf es von dir! Denn es ist dir besser, eins von deinen Gliedern geht dir verloren, als daß dein ganzer Leib in die Hölle geworfen werde.',
        30: 'Und wenn dich deine rechte Hand zur Sünde verführt, haue sie ab und wirf sie von dir! Denn es ist dir besser, eins von deinen Gliedern geht dir verloren, als daß dein ganzer Leib in die Hölle fahre.',
        31: 'Ferner ist gesagt worden: Wer sein Weib entläßt, der soll ihr einen Scheidebrief geben.',
        32: 'Ich aber sage euch: Wer sein Weib entläßt — abgesehn von dem Falle, daß sie Unzucht getrieben —, der setzt sie der Gefahr aus, daß sie Ehebruch begeht; und wer eine (von ihrem Mann) entlassene Frau zum Weibe nimmt, der begeht damit einen Ehebruch.',
        33: 'Weiterhin habt ihr gehört, daß zu den Alten gesagt worden ist: Du sollst nicht falsch schwören, du sollst vielmehr dem Herrn deine Eide (und Gelübde) erfüllen.',
        34: 'Ich aber sage euch: Ihr sollt überhaupt nicht schwören: weder bei dem Himmel, denn er ist Gottes Thron,',
        35: 'noch bei der Erde, denn sie ist seiner Füße Schemel, noch bei Jerusalem, denn sie ist des großen Königs Stadt.',
        36: 'Du sollst auch nicht bei deinem Haupte schwören; denn du bist nicht imstande, ein einziges Haar weiß oder schwarz zu machen.',
        37: 'In eurer Rede sei vielmehr das Ja ein Ja, das Nein ein Nein; was dem hinzugefügt wird, stammt von dem Bösen.',
        38: 'Ihr habt gehört, daß gesagt worden ist: Auge um Auge und Zahn um Zahn!',
        39: 'Ich aber sage euch: Setzt einem bösen Menschen keinen Widerstand entgegen! Im Gegenteil: Wer dich auf die rechte Wange schlägt, dem halte auch die andre hin!',
        40: 'Und wer dir durch eine Klage vor Gericht dein Unterkleid entreißen will, dem gib freiwillig auch dein Oberkleid.',
        41: 'Und wer dein Geleit für eine Meile haben will, mit dem gehe zwei!',
        42: 'Wer dich um etwas bittet, dem gib; und wer etwas von dir borgen will, von dem wende dich nicht ab!',
        43: 'Ihr habt gehört, daß gesagt worden ist: Du sollst deinen Nächsten lieben und deinen Feind hassen!',
        44: 'Ich aber sage euch: Liebet eure Feinde und betet für eure Verfolger!',
        45: 'Dann zeigt ihr euch als Söhne eures Vaters im Himmel. Denn er läßt seine Sonne aufgehn über Böse und Gute und läßt regnen über Gerechte und Ungerechte.',
        46: 'Denn wenn ihr nur die liebt, die euch lieben, was für eine Belohnung habt ihr da zu erwarten? Tun das nicht auch die Zöllner?',
        47: 'Und wenn ihr nur mit euern Volksgenossen verkehrt, was tut ihr da Besonderes? Tun das nicht auch die Heiden?',
        48: 'Darum sollt ihr vollkommen sein, wie euer himmlischer Vater vollkommen ist.',
    },
    6: {
        1: 'Hütet euch, eure Frömmigkeit vor den Augen der Leute zu üben, um von ihnen bewundert zu werden! Sonst habt ihr keine Belohnung von euerm Vater im Himmel zu erwarten.',
        2: 'Wenn du nun Liebeswerke übst, laß es nicht vor dir ausposaunen, wie es die Heuchler machen in den Versammlungshäusern und auf den Straßen, um vor den Leuten gelobt zu werden. Wahrlich, ich sage euch: Sie haben ihre Belohnung schon weg.',
        3: 'Sondern, wenn du Liebeswerke übst, so soll deine linke Hand nicht wissen, was deine rechte tut,',
        4: 'damit dein Wohltun im Verborgenen bleibe. Dann wir dein Vater, der ins Verborgene sieht, es dir vergelten.',
        5: "Und wenn ihr betet, macht's nicht wie die Heuchler! Die lieben es, in den Versammlungshäusern und an den Straßenecken zu stehen und zu beten, um den Leuten aufzufallen. Wahrlich, ich sage euch: Sie haben ihre Belohnung schon weg.",
        6: 'Sondern wenn du beten willst, so geh in deine Kammer, schließ die Tür hinter dir und bete dann zu deinem Vater, der im Verborgenen wohnt! Dann wird dein Vater, der ins Verborgene sieht, es dir vergelten.',
        7: 'Beim Beten plappert nicht gedankenlos wie die Heiden! Die meinen, sie finden Erhörung, wenn sie viel Worte machen.',
        8: 'Gleicht ihnen nicht! Denn euer Vater weiß was ihr bedürft, noch ehe ihr ihn bittet.',
        9: 'Ihr sollt nun also beten: Unser Vater, der du bist im Himmel! Dein Name werde geheiligt!',
        10: 'Dein Königreich komme! Dein Wille geschehe, wie im Himmel, also auch auf Erden!',
        11: 'Unser Brot für morgen gib uns heute!',
        12: 'Und vergib uns unsere Schulden, wie auch wir vergeben unseren Schuldnern.',
        13: 'Und führe uns nicht in Versuchung! Sondern bewahre uns vor dem Bösen!',
        14: 'Denn wenn ihr den Menschen ihre Fehltritte vergebt, so wird euch euer himmlischer Vater auch vergeben.',
        15: 'Wenn ihr aber den Menschen nicht vergebt, so wird euch euer Vater eure Fehltritte auch nicht vergeben.',
        16: 'Wenn ihr fastet, schaut nicht trübselig drein wie die Heuchler! Die entstellen ihr Gesicht, damit die Leute ihr Fasten sehen. Wahrlich, ich sage euch: Sie haben ihre Belohnung schon weg.',
        17: 'Wenn du fastest, so salbe dein Haupt und wasche dein Antlitz,',
        18: 'damit die Leute dein Fasten nicht sehen, sondern allein dein Vater, der im Verborgnen wohnt. Dann wird dein Vater, der ins Verborgne sieht, es dir vergelten.',
        19: 'Sammelt euch nicht Schätze hier auf Erden, wo Motten und Würmer Zerstörung üben, und wo Diebe einbrechen und stehlen.',
        20: 'Sammelt euch vielmehr Schätze im Himmel, wo keine Motten und Würmer Zerstörung üben, und wo keine Diebe einbrechen und stehlen.',
        21: 'Denn wo dein Schatz ist, da ist auch dein Herz.',
        22: 'Des Leibes Leuchte ist das Auge. Ist dein Auge gesund, so ist dein ganzer Leib im Lichte.',
        23: 'Ist aber dein Auge krank, so ist dein ganzer Leib in Finsternis. Wenn nun das Licht in dir verfinstert ist, wie groß muß dann die Finsternis sein!',
        24: 'Niemand kann zwei Herren dienen. Denn er wird den einen hassen und den andern lieben oder doch dem einen anhangen und gering von dem andern denken. Ihr könnt nicht Gott und zugleich dem Gelde dienen.',
        25: 'Darum sage ich euch: Sorgt nicht ängstlich für euer Leben, was ihr essen und trinken sollt, auch nicht für euern Leib, was ihr anziehen sollt. Ist nicht das Leben mehr wert als die Nahrung? Und steht der Leib nicht höher als die Kleidung?',
        26: 'Seht auf die Vögel, die unter dem Himmel fliegen! Sie säen nicht, sie ernten nicht, sie sammeln nichts in Speicher; trotzdem ernährt sie euer himmlischer Vater. Steht ihr denn nicht viel höher als sie?',
        27: 'Wer von euch kann mit all seinem Sorgen sein Leben auch nur um eine kurze Spanne Zeit verlängern?',
        28: 'Betrachtet doch die wilden Lilien auf dem Felde, wie sie wachsen! Sie mühen sich nicht ab, sie spinnen nicht.',
        29: 'Und doch — das sage ich euch — ist selbst Salomo in all seiner (königlichen) Pracht nicht so (herrlich) gekleidet gewesen wie eine von ihnen.',
        30: 'Wenn Gott nun das Gras auf dem Felde, das heute noch in Blüte steht und morgen in den Ofen geworfen wird, so herrlich kleidet, wird er da nicht viel mehr euch Kleidung geben, ihr Kleingläubigen?',
        31: "Darum sollt ihr nicht ängstlich sorgen und sagen: 'Was sollen wir essen? Was sollen wir trinken? Was sollen wir anziehen?'",
        32: 'Denn das sind lauter Fragen, womit sich die Heiden beschäftigen. Euer himmlischer Vater weiß ja, daß ihr dies alles nötig habt.',
        33: 'Trachtet vielmehr vor allem nach dem Königreiche Gottes und nach der Gerechtigkeit, die er verlangt; dann soll euch alles dies daneben auch zuteil werden.',
        34: 'Seid also nicht besorgt im Blick auf morgen; denn der morgende Tag wird selber für sich sorgen. Jeder Tag hat genug an seiner eigenen Mühsal.',
    },
    7: {
        1: 'Richtet nicht (hart und lieblos), damit ihr nicht (einst ebenso) gerichtet werdet!',
        2: 'Denn ganz ebenso, wie ihr jetzt richtet, sollt ihr dereinst gerichtet werden; und mit dem Maß, womit ihr messet, soll euch (das Urteil) zugemessen werden.',
        3: 'Warum siehst du den Splitter in deines Bruders Auge, während du den Balken in deinem Auge nicht bemerkst?',
        4: "Oder wie kannst du dir herausnehmen, zu deinem Bruder zu sagen: 'Laß mich den Splitter aus deinem Auge entfernen', während in deinem Auge der Balken steckt?",
        5: 'Du Heuchler, entferne zunächst den Balken aus deinem Auge! Dann erst magst du sehn, wie du den Splitter aus deines Bruders Auge entfernst.',
        6: 'Gebt das Heilige nicht den Hunden preis und werft eure Perlen nicht den Schweinen vor! Sie könnten sie mit ihren Füßen zertreten und sich dann gegen euch wenden und euch zerreißen.',
        7: 'Bittet, so wird euch gegeben! Suchet, so werdet ihr finden! Klopfet an, so wird euch aufgetan!',
        8: 'Denn wer bittet, der empfängt; wer sucht, der findet; und wer anklopft, dem wird aufgetan.',
        9: 'Es wird doch niemand unter euch seinem Sohne, der ihn um Brot bittet, einen Stein geben',
        10: 'oder ihm, wenn er um einen Fisch bittet, eine Schlange reichen.',
        11: 'Wißt ihr nun, obwohl ihr böse seid, euern Kindern gute Gaben zu geben: wieviel mehr wird da euer Vater im Himmel Gutes geben denen, die ihn darum bitten!',
        12: 'Alles nun, was ihr von den Leuten erwartet, das sollt ihr ihnen auch erweisen. Dies ist der Inhalt des Gesetzes und der Propheten.',
        13: 'Tretet ein durch das enge Tor! Denn weit und breit ist der Weg, der ins Verderben führt, und viele wählen diesen Weg.',
        14: 'Wie eng dagegen ist das Tor und wie schmal der Weg, der in das Leben führt, und wie wenige sind es, die ihn finden!',
        15: 'Hütet euch vor den falschen Propheten! Sie kommen in Schafskleidern zu euch, inwendig aber sind sie reißende Wölfe.',
        16: 'An ihren Früchten sollt ihr sie erkennen. Man kann doch nicht Trauben sammeln von Dornbüschen oder Feigen von Distelgestrüpp.',
        17: 'Ebenso bringt jeder edle Baum auch nützliche Früchte, ein schädlicher Baum aber bringt verderbliche Früchte.',
        18: 'Ein edler Baum kann nicht verderbliche Früchte tragen, und ein schädlicher Baum kann nicht nützliche Früchte tragen.',
        19: 'Jeder Baum, der nicht nützliche Früchte bringt, wird abgehauen und ins Feuer geworfen.',
        20: 'An ihren Früchten also sollt ihr sie erkennen.',
        21: "Nicht jeder, der zu mir sagt: 'Herr, Herr!' wird eingehen in das Königreich der Himmel, vielmehr nur der, der da erfüllt den Willen meines Vaters, der im Himmel ist.",
        22: "An jenem Tage werden viele zu mir sprechen: 'Herr, Herr! Haben wir nicht kraft deines Namens geweissagt? Haben wir nicht kraft deines Namens böse Geister ausgetrieben? Haben wir nicht kraft deines Namens viele Wunder gewirkt?",
        23: "Dann werde ich ihnen frei und offen sagen: 'Nie habe ich euch gekannt! Hinweg von mir, ihr Übeltäter!",
        24: 'Wer nun diese meine Worte hört und befolgt, gleicht einem klugen Manne, der sein Haus auf Felsenboden baut.',
        25: 'Wenn dann der Regen niederströmt und Überschwemmung kommt, und wenn die Winde wehen und treffen auf das Haus, so fällt es nicht; denn seine Mauer ruht auf Felsengrund.',
        26: 'Wer aber diese meine Worte hört und nicht befolgt, gleicht einem törichten Manne, der sein Haus auf sandigen Boden baut.',
        27: 'Wenn dann der Regen niederströmt und Überschwemmung kommt, und wenn die Winde wehen und stoßen auf das Haus, so fällt es! Ja es wird ein großer Trümmerhaufen!"',
        28: 'Als Jesus diese Rede vollendet hatte, war die Volksmenge von seiner Lehre ergriffen und betroffen.',
        29: 'Denn er lehrte sie wie einer, der dazu (göttliche) Vollmacht hatte, und nicht wie ihre Schriftgelehrten.',
    },
    8: {
        1: 'Als er von der Bergeshöhe hinabging, folgten ihm große Scharen',
        2: 'Da näherte sich ihm ein Aussätziger, fiel vor ihm nieder und sprach: "Herr, wenn du willst, so kannst du mich reinigen."',
        3: 'Jesus streckte sein Hand aus, rührte ihn an und sprach: "Ich will es, sei gereinigt!" Sofort ward er von seinem Aussatz rein.',
        4: 'Und Jesus sprach zu ihm: "Hüte dich, irgendwie davon zu reden; doch geh, zeige dich dem Priester und bring das Opfer dar, das Mose vorgeschrieben hat, zum Zeugnis für die Leute!"',
        5: 'Als er nach Kapernaum zurückkam, nahte ihm ein Hauptmann mit den Worten:',
        6: '"Herr, mein Diener liegt gelähmt zu Hause und hat große Schmerzen."',
        7: 'Jesus sprach zu ihm: "Ich soll kommen und ihn heilen?"',
        8: 'Der Hauptmann antwortete: "Herr, ich bin nicht wert, daß du unter mein Dach trittst; sondern sprich nur ein Wort, so wird mein Diener schon genesen.',
        9: "Denn auch ich bin zwar einem Vorgesetzten untergeben, aber ich habe Kriegsleute unter mir. Sage ich nun zu dem einen: 'Geh!', so geht er, zu dem anderen: 'Komm!', so kommt er, und zu meinem Knechte: 'Tue das!', so tut er's",
        10: 'Als Jesus das hörte, wunderte er sich und sprach zu seinen Begleitern: "Wahrlich, sich sage euch: Nirgends habe ich solchen Glauben in Israel gefunden.',
        11: 'Ich tue euch aber kund: Viele werden von Osten und Westen kommen und mit Abraham, Isaak und Jakob im Königreiche der Himmel am Mahle teilnehmen.',
        12: 'Doch die geborenen Erben des Königreichs werden in die Finsternis, die draußen ist, verstoßen werden; dort wird lautes Klagen und Zähneknirschen sein."',
        13: 'Dann sagte Jesus zu dem Hauptmann: "Geh! Dir geschehe, wie du geglaubt!" Und sein Diener ward gesund in jener Stunde.',
        14: 'Dann kam Jesus in des Petrus Haus und sah dessen Schwiegermutter fieberkrank daniederliegen.',
        15: 'Da berührte er ihre Hand, und das Fieber verließ sie. Nun erhob sie sich von ihrem Lager und wartete ihm bei der Mahlzeit auf.',
        16: 'Am Abend brachte man viele Besessene zu ihm; er trieb die (bösen) Geister durch sein Machtwort aus und heilte alle Leidenden.',
        17: 'So erfüllte sich der Ausspruch des Propheten Jesaja: Er hat unsre Gebrechen hinweggenommen, und unsere Krankheiten hat er beseitigt.',
        18: 'Als Jesus dann eine Menge Volks um sich sah, ließ er sich an das andere Ufer fahren.',
        19: 'Da nahte ihm ein Schriftgelehrter mit den Worten: "Meister, ich will dir folgen, wohin du gehst."',
        20: 'Jesus sprach zu ihm: "Die Füchse haben Höhlen, und die Vögel, die unter dem Himmel fliegen, haben Nester; doch der Menschensohn hat keine Stätte, wo er sein Haupt niederlegen kann."',
        21: 'Ein anderer seiner Jünger sprach zu ihm: "Herr, erlaube mir, daß ich vorher hingehe und meinen Vater begrabe!"',
        22: 'Jesus aber antwortete ihm: "Folge mir und laß die Toten ihre Toten begraben!"',
        23: 'Dann stieg er in ein Fischerboot, und seine Jünger begleiteten ihn.',
        24: 'Plötzlich erhob sich ein heftiger Sturm auf dem See, so daß die Wogen ins Fahrzeug schlugen. Er aber schlief.',
        25: 'Da traten die Jünger zu ihm und weckten ihn mit dem Rufe: "Herr, hilf uns, wir ertrinken!"',
        26: 'Er aber sprach zu ihnen: "Was seid ihr so furchtsam, ihr Kleingläubigen?" Dann stand er auf und schalt die Winde und den See. Da ward eine tiefe Stille.',
        27: 'Die Leute aber sprachen voll Verwunderung: "Was ist das für ein Mann, daß ihm sogar Wind und Wogen gehorchen!"',
        28: 'Als er ans andre Ufer kam in das Gebiet der Gadarener, begegneten ihm zwei Besessene: die kamen aus den Felsengräbern und waren sehr gefährlich, so daß niemand jenes Weges gehen konnte.',
        29: 'Und sie fingen an zu schreien: "Was haben wir mit dir zu schaffen, du Gottessohn? Bist du hierhergekommen, um uns vor der Zeit zu quälen?"',
        30: 'Nun weidete in der Ferne eine große Schweineherde.',
        31: 'Da baten ihn die bösen Geister: "Treibst du uns aus, so laß uns in die Schweineherde fahren!"',
        32: 'Er sprach zu ihnen: "Geht!" Da fuhren sie aus und gingen in die Schweine. Nun stürmte die ganze Herde den Abhang hinunter in den See und kam in den Fluten um',
        33: 'Die Hirten aber flohen. Bei ihrer Ankunft in der Stadt erzählten sie den ganzen Vorgang, und was mit den Besessenen geschehen war.',
        34: 'Da gingen alle Einwohner hinaus, Jesus entgegen, und als sie ihn trafen, baten sie ihn, er möge ihr Gebiet verlassen.',
    },
    9: {
        1: 'Er stieg nun in ein Fahrzeug, fuhr über den See und kam in seine Stadt.',
        2: 'Dort brachte man auf einem Tragbett einen Gelähmten zu ihm. Als Jesus ihren Glauben sah, sprach er zu dem Gelähmten: "Sei getrost, mein Sohn, deine Sünden sind dir vergeben!"',
        3: 'Da dachten einige Schriftgelehrte bei sich: "Der Mann lästert Gott."',
        4: 'Jesus durchschaute ihre Gedanken und sprach: "Warum denkt ihr Böses in euern Herzen?',
        5: "Was ist denn leichter, zu sagen: 'Deine Sünden sind dir vergeben' oder das Wort zu sprechen: 'Steh auf und wandle'?",
        6: 'Ihr sollt aber sehen, daß der Menschensohn die Vollmacht hat, auf Erden Sünden zu vergeben." Nun wandte er sich zu dem Gelähmten und sprach: "Steh auf, nimm dein Bett und geh nach Hause!"',
        7: 'Da stand er auf und ging nach Hause.',
        8: 'Bei diesen Anblick wurden die Leute mit heiliger Scheu erfüllt und priesen Gott, der den Menschen solche Vollmacht gegeben.',
        9: 'Als Jesus von dort weiterging, sah er einen Mann, mit Namen Matthäus, vor seinem Zollhaus sitzen, und er sprach zu ihm: "Folge mir!" Da stand er auf und folgte ihm.',
        10: 'Während nun Jesus in des Matthäus Haus zu Gast war, fanden sich auch viele Zöllner und Sünder ein und nahmen mit Jesus und seinen Jüngern an dem Mahle teil.',
        11: 'Als das die Pharisäer sahen, sprachen sie zu seinen Jüngern: "Warum ißt euer Meister mit den Zöllnern und Sündern?"',
        12: 'Jesus hörte das und erwiderte: "Die Gesunden bedürfen des Arztes nicht, sondern die Kranken.',
        13: 'Geht aber hin und lernt, was das Wort bedeutet: Barmherzigkeit will ich und nicht Opfer. Denn ich bin nicht gekommen, um Gerechte zu berufen, sondern Sünder."',
        14: 'Darauf kamen die Jünger des Johannes zu ihm und sprachen: "Warum fasten wir und die Pharisäer so oft, während deine Jünger nicht fasten?"',
        15: 'Jesus antwortete ihnen: "Können denn die Hochzeitsgäste trauern, solange der Bräutigam bei ihnen ist? Es kommt jedoch die Zeit, wo ihnen der Bräutigam entrissen ist, dann werden sie fasten.',
        16: 'Niemand setzt einen Flicken von neuem Tuch auf ein altes Kleid. Sonst reißt der Einsatz noch an anderen Stellen etwas von dem Kleid weg, und der Riß wird desto ärger.',
        17: 'Man gießt auch nicht neuen Wein in alte Schläuche. Sonst reißen die Schläuche: dann fließt der Wein aus, und die Schläuche sind verloren. Man gießt vielmehr neuen Wein in neue Schläuche: so halten sich beide."',
        18: 'Als er so zu ihnen redete, da kam ein Vorsteher, der fiel vor ihm nieder und sprach: "Meine Tochter ist soeben gestorben; aber komm und leg deine Hand auf sie, dann wird sie wieder lebendig!"',
        19: 'Jesus erhob sich und folgte ihm mit seinen Jüngern.',
        20: 'Und sieh, eine Frau, die schon zwölf Jahre am Blutfluß litt, trat von hinten an ihn heran und berührte die Quaste seines Mantels.',
        21: 'Denn sie dachte bei sich: wenn ich nur seinen Mantel berühre, so werde ich gesund.',
        22: 'Jesus wandte sich um, erblickte sie und sprach: "Sei getrost, meine Tochter; dein Glaube hat dich schon gesund gemacht!" Und von dem Augenblick an ward die Frau gesund.',
        23: 'Dann kam Jesus in das Haus des Vorstehers. Beim Anblick der Flötenspieler und der lärmenden Menge aber sprach er:',
        24: '"Geht hinaus!" Denn das Mädchen ist nicht tot, es schläft nur." Da verlachten sie ihn.',
        25: 'Als aber die Leute aus dem Hause geschickt waren, trat er ein und faßte das Mädchen bei der Hand. Da stand es auf.',
        26: 'Und die Kunde davon verbreitete sich in jener ganzen Gegend.',
        27: 'Als Jesus von dort weiterging, folgten ihm zwei Blinde, die riefen laut: "Erbarme dich unser, Sohn Davids!"',
        28: 'Als dann Jesus in sein Haus kam, traten die Blinden zu ihm. Jesus fragte sie: "Glaubt ihr, daß ich dies tun kann?" Sie antworteten: "Ja, Herr!"',
        29: 'Nun berührte er ihre Augen mit den Worten: "Nach euerm Glauben geschehe euch!"',
        30: 'Da taten sich ihre Augen auf. Und Jesus befahl ihnen streng: "Gebt acht, daß es niemand erfahre!"',
        31: 'Sobald sie aber das Haus verlassen hatten, machten sie ihn in jener ganzen Gegend bekannt.',
        32: 'Gerade als sie weggingen, brachte man einen Menschen zu ihm, der durch den Einfluß eines bösen Geistes stumm war.',
        33: 'Doch nach der Austreibung des bösen Geistes konnte der Stumme reden. Da verwunderten sich die Leute und sprachen: "So etwas hat man noch nie in Israel erlebt."',
        34: 'Die Pharisäer aber sagten: "Im Bunde mit dem obersten der bösen Geister treibt er die Geister aus."',
        35: 'So durchwanderte Jesus alle Städte und Dörfer: er lehrte in ihren Versammlungshäusern, verkündigte die Frohe Botschaft vom Königreich und heilte allerlei Krankheiten und Gebrechen.',
        36: 'Beim Anblick der Volksscharen aber ward er von Mitleid erfüllt, denn sie waren abgetrieben und ermattet wie Schafe ohne Hirten.',
        37: 'Da sprach er zu seinen Jüngern: "Die Ernte ist groß, aber der Arbeiter sind wenig.',
        38: 'Darum bittet den Herrn der Ernte, daß er Arbeiter auf sein Erntefeld sende!"',
    },
    10: {
        1: 'Dann rief er seine zwölf Jünger herbei und gab ihnen Vollmacht, unreine Geister auszutreiben und allerlei Krankheiten und Gebrechen zu heilen. Dies sind aber die Namen der zwölf Apostel:',
        2: 'Simon, genannt Petrus, — als erster — und seinen Bruder Andreas; Jakobus, des Zebedäus Sohn, und sein Bruder Johannes;',
        3: 'Philippus und Bartholomäus; Thomas und der Zöllner Matthäus; Jakobus, des Alphäus Sohn, und Lebbäus mit dem Beinamen Thaddäus;',
        4: 'Simon der Eiferer und Judas aus Kariot, der ihn verraten hat.',
        5: 'Diese Zwölf sandte Jesus aus mit folgendem Auftrag: "Nehmt euern Weg nicht zu den Heiden und betretet keine Stadt der Samariter!',
        6: 'Geht vielmehr zu den verirrten Schafen des Hauses Israel!',
        7: "Geht und verkündigt: 'Das Königreich der Himmel ist nahe herbeigekommen!'",
        8: "Heilt die Kranken, erweckt die Toten, reinigt die Aussätzigen, treibt die bösen Geister aus! Umsonst habt ihr's empfangen, umsonst sollt ihr's geben.",
        9: 'Steckt euch kein Gold, kein Silber und kein Kupfergeld in eure Gürtel!',
        10: 'Nehmt keine Ranzen mit euch auf den Weg, auch nicht zwei Unterkleider, keine Schuhe, keinen Wanderstab! Denn der Arbeiter ist seiner Nahrung wert.',
        11: 'Kommt ihr in eine Stadt oder in ein Dorf, so erkundigt euch, wer dort (euch aufzunehmen) verdient; bleibt dann so lange da, bis ihr weiterzieht!',
        12: 'Bei euern Eintritt aber wünscht dem Hause Frieden!',
        13: 'Ist nun das Haus es wert, so wird der Friede, den ihr wünscht, ihm auch zuteil; verdient es ihn aber nicht, so fällt der Friedensgruß auf euch zurück.',
        14: 'Und wo man euch nicht aufnimmt noch eure Botschaft hören will, ein solches Haus und eine solche Stadt verlasset und schüttelt den Staub von euern Füßen!',
        15: 'Wahrlich, ich sage euch: Dem Lande Sodom und Gomorra wird es am Tage des Gerichts viel besser gehn als solcher Stadt.',
        16: 'Ich sende euch jetzt wie Schafe mitten unter Wölfe. So seid denn klug wie die Schlangen, aber auch ohne Falsch wie die Tauben!',
        17: 'Seid aber vor den Menschen auf der Hut! Denn sie werden euch den Gerichten überliefern, und in ihren Versammlungshäusern werden sie euch geißeln.',
        18: 'Ja man wird euch vor Statthalter und Könige führen um meinetwillen, damit ihr ihnen und den Heiden ein Zeugnis gebt.',
        19: 'Stellt man euch nun vor ein Gericht, so macht euch keine Sorte, wie oder was ihr reden sollt! Denn in jenem Augenblick wird euch das rechte Wort gegeben werden.',
        20: 'Ihr seid es ja nicht, die dann reden, sondern es ist euers Vaters Geist, der durch euch redet.',
        21: 'Ein Bruder aber wird den andern zum Tode bringen und Väter ihre Kinder; ja Kinder werden sich erheben gegen ihre Eltern und sie töten lassen.',
        22: 'Und allgemein wird man euch hassen, weil ihr Bekenner meines Namens seid. Wer aber ausharrt bis ans Ende, der soll errettet werden.',
        23: 'Verfolgen sie euch nun in einer Stadt, so flieht in eine andere! Wahrlich, ich sage euch: Vor des Menschensohnes Kommen wird eure Arbeit an den Städten Israels noch nicht vollendet sein.',
        24: "Ein Schüler darf kein anderes Los erwarten als sein Lehrer; ein Sklave soll's nicht besser haben wollen als sein Herr.",
        25: 'Der Schüler muß zufrieden sein, wenn es ihm geht wie seinem Lehrer, der Sklave, wenn es ihm geht wie seinen Herrn. Hat man den Hausherrn mit dem Namen Beelzebul geschmäht, um wieviel mehr wird man seine Hausgenossen so schmähen.',
        26: 'Fürchtet euch darum nicht vor ihnen! Denn nichts ist so verhüllt, daß es nicht einst enthüllt würde; und nichts ist so verborgen, daß es nicht einst gesehen würde.',
        27: 'Was ich euch im geheimen sage, das verkündigt öffentlich; und was ich euch ins Ohr flüstere, das predigt auf den Dächern!',
        28: 'Seid dabei ohne Furcht vor denen, die wohl den Leib, doch nicht die Seele töten können! Seid aber voller Furcht vor dem, der Seele und Leib in der Hölle verderben kann!',
        29: 'Verkauft man nicht zwei Sperlinge für fünf Pfennige? Trotzdem fällt kein einziger von ihnen zu Boden ohne euers Vaters Willen.',
        30: 'Bei euch sind aber sogar die Haare euers Hauptes allesamt gezählt.',
        31: 'Darum habt keine Furcht! Ihr seid mehr wert als viele Sperlinge.',
        32: 'Wer sich nun zu mir bekennt vor den Menschen, zu dem will ich mich auch bekennen vor meinem Vater im Himmel.',
        33: 'Wer mich aber verleugnet vor den Menschen, den will ich auch verleugnen vor meinem Vater im Himmel.',
        34: 'Denkt nicht, ich sei gekommen, um Frieden auf die Erde zu bringen! Ich bin nicht gekommen, um Frieden zu bringen, sondern Krieg.',
        35: 'Denn ich bin gekommen, um zu entzweien Vater und Sohn, Mutter und Tochter, Schwiegermutter und Schwiegertochter;',
        36: 'und die eignen Hausgenossen wird man zu Feinden haben.',
        37: 'Wer Vater oder Mutter mehr liebt als mich, der ist mein nicht wert; wer Sohn oder Tochter mehr liebt als mich, der ist mein nicht wert.',
        38: 'Wer nicht sein Kreuz auf sich nimmt, und mir nachfolgt, der ist mein nicht wert.',
        39: 'Sein Leben retten heißt: es verlieren! Sein Leben verlieren um meinetwillen heißt: es retten!',
        40: 'Wer euch aufnimmt, der nimmt mich auf; und wer mich aufnimmt, der nimmt den auf, der mich gesandt hat.',
        41: 'Wer einen Propheten als solchen aufnimmt, der wird den Lohn empfangen, den ein Prophet empfängt; wer einen Gerechten als solchen aufnimmt, der wird den Lohn empfangen, den ein Gerechter empfängt.',
        42: 'Und wer einem dieser kleinen Kinder hier auch nur einen Becher frischen Wassers zum Trunke reicht, weil es mein Jünger ist, der soll — das sage ich euch feierlich — gewiß nicht seines Lebens verlustig gehen!"',
    },
    11: {
        1: 'Als Jesus seinen zwölf Jüngern diese Weisungen erteilt hatte, ging er von dort weiter, um in den Städten des Landes zu lehren und zu predigen.',
        2: 'Als Johannes im Gefängnis von der Wirksamkeit des Messias hörte, ließ er ihn durch seine Jünger fragen:',
        3: '"Bist du es, der kommen soll, oder müssen wir auf einen anderen warten?"',
        4: 'Jesus antwortete ihnen: "Geht und berichtet Johannes, was ihr hört und seht:',
        5: 'Blinde werden sehend und Lahme gehen, Aussätzige werden rein und Taube hören, ja Tote werden auferweckt und Armen wird die Heilsbotschaft verkündigt;',
        6: 'und selig ist, wer an mir nicht irre wird!"',
        7: 'Als die Boten weggingen, begann Jesus zu den Volksscharen von Johannes zu reden: "Warum seid ihr einst in die Wüste hinausgegangen? Wolltet ihr euch ein Schilfrohr ansehen, das sich im Winde hin und her bewegte? Doch sicher nicht!',
        8: 'Warum seid ihr denn hinausgegangen? Wolltet ihr einen feingekleideten Weltmann sehen? Solche feingekleidete Leute finden sich an den Königshöfen.',
        9: 'Warum seid ihr denn hinausgegangen? Wolltet ihr einen Propheten sehen? Ja ich sage euch: Dieser Mann ist noch weit mehr als ein Prophet.',
        10: 'Denn er ist es, von dem geschrieben steht: Sieh, ich sende meinen Boten vor dir her, der deinen Weg vor dir bereiten soll',
        11: 'Wahrlich, ich sage euch: Unter allen Weibersöhnen ist kein Größerer aufgetreten als Johannes der Täufer; doch der Kleinste im Königreich der Himmel ist größer als er.',
        12: 'Aber seit dem Auftreten Johannes des Täufers bis jetzt wird das Königreich der Himmel gestürmt. Und die Stürmer reißen es an sich.',
        13: 'Denn alle Propheten und das Gesetz haben davon geweissagt bis auf Johannes.',
        14: "Und wollt ihr's gelten lassen: er ist der Elia, der kommen soll.",
        15: 'Wer Ohren hat, der höre!',
        16: 'Wem soll ich aber das Volk von heute vergleichen? Es gleicht Kindern, die auf der Straße sitzen und ihren Gespielen zurufen:',
        17: 'Wir haben euch die Flöte gespielt, doch ihr habt nicht getanzt; wir haben ein Klagelied gesungen, doch ihr habt nicht geweint.',
        18: "Johannes ist aufgetreten und hat streng enthaltsam gelebt in Speise und Trank; da sagte man: 'Er ist von einem bösen Geist besessen!'",
        19: 'Der Menschensohn ist aufgetreten und ißt und trinkt wie andere; da sagt man nun: \'Seht, er ist ein Fresser und Weintrinker, der Zöllner und Sünder Freund\'. Aber doch ist die Weisheit (Gottes) durch ihr ganzes Tun gerechtfertigt worden."',
        20: 'Dann fing er an, die Städte zu schelten, in denen seine meisten Wundertaten geschehen waren, und die sich trotzdem nicht bekehrt hatten:',
        21: '"Weh dir, Chorazin! Wehe dir, Bethsaida. Denn wären in Tyrus und Sidon die Wundertaten geschehen, die in euch geschehen sind, sie hätten sich schon längst, in Sack und Asche sitzend, bekehrt.',
        22: 'Doch ich sage euch: Es wird Tyrus und Sidon am Tage des Gerichts erträglicher gehen als euch.',
        23: 'Und du, Kapernaum, meinst du vielleicht, du wirst bis zum Himmel erhoben? In die Tiefe der Unterwelt sollst du hinabgestürzt werden! Denn wären in Sodom die Wundertaten geschehen, die in dir geschehen sind, es stünde noch heutigentags.',
        24: 'Doch ich sage euch: Es wird dem Lande Sodom am Tage des Gerichts erträglicher gehen als dir."',
        25: 'Zu jener Zeit tat Jesus seinen Mund auf und sprach: "Ich preise dich, o Vater, Herr des Himmels und der Erde, daß du dies den Weisen und Verständigen verborgen und es den Einfältigen offenbart hast.',
        26: "Ja, Vater, so hat dir's gefallen!",
        27: 'Alles ist mir von meinem Vater übergeben worden. Und niemand kennt den Sohn vollkommen als nur der Vater; auch kennt niemand den Vater recht als nur der Sohn und der, dem der Sohn es offenbaren will.',
        28: 'Kommt alle her zu mir, die ihr euch abmüht und von Last gedrückt seid! Ich will euch Ruhe schenken.',
        29: 'Nehmt mein Joch auf euch und lernt von mir; denn ich bin mild und voller Herzensdemut; dann werdet ihr Ruhe finden für eure Seelen.',
        30: 'Denn mein Joch ist sanft, und meine Last ist leicht."',
    },
    12: {
        1: 'Zu jener Zeit ging Jesus an einem Sabbat durch Getreidefelder. Seine Jünger aber hatten Hunger; darum begannen sie, Ähren abzureißen und die Körner zu essen.',
        2: 'Das sahen die Pharisäer und sprachen zu ihm: "Sieh, deine Jünger tun, was nicht erlaubt ist am Sabbat."',
        3: 'Er aber antwortete ihnen: "Habt ihr nicht gelesen, was David tat, als ihn und seine Begleiter hungerte?',
        4: 'Wie er in das Haus Gottes trat und die Schaubrote aß, die doch er und seine Begleiter nicht essen durften, sondern nur die Priester?',
        5: 'Habt ihr ferner nicht gelesen im Gesetz, daß die Priester im Tempel auch am Sabbat tätig sind, ohne sich zu versündigen?',
        6: 'Doch ich sage euch: Hier ist etwas Größeres als der Tempel.',
        7: 'Verstündet ihr aber die Bedeutung des Wortes: Barmherzigkeit will ich und nicht Opfer, so hättet ihr die Schuldlosen nicht verurteilt.',
        8: 'Denn der Menschensohn ist Herr des Sabbats."',
        9: 'Als er von dort weiterging, kam er in ihr Versammlungshaus.',
        10: 'Da war ein Mann mit einem abgestorbenen Arm, und sie fragten ihn: "Ist es erlaubt, am Sabbat zu heilen?" Denn sie suchten einen Grund, ihn zu verklagen.',
        11: 'Er aber antwortete ihnen: "Fiele einem von euch am Sabbat sein einziges Schaf in eine Grube, zöge er\'s da nicht sofort heraus?',
        12: 'Steht nun ein Mensch nicht hoch über einem Schaf? Also darf man auch am Sabbat Gutes tun."',
        13: 'Dann sprach er zu dem Mann: "Strecke deinen Arm aus!" Da streckte er ihn aus, und er ward wiederhergestellt und gesund wie der andere.',
        14: 'Als dann die Pharisäer den Gottesdienst verließen, berieten sie sich miteinander wider ihn, wie sie ihn zu Tode bringen könnten.',
        15: 'Aber Jesus erfuhr das und verließ jene Gegend. Viele begleiteten ihn, und er heilte alle.',
        16: 'Aber er schärfte ihnen ein, sie sollten ihn nicht öffentlich bekanntmachen,',
        17: 'damit sich der Ausspruch des Propheten Jesaja erfüllte:',
        18: 'Das ist mein Knecht, den ich erwählt, und mein Geliebter, den mein Herz erkoren. Ich lege meinen Geist auf ihn, und er soll den Völkern Recht verkünden.',
        19: 'Er wird nicht zanken und nicht schreien, und seine Stimme schallt nicht auf den Straßen.',
        20: 'Geknicktes Rohr zerbricht er nicht, und glimmenden Docht löscht er nicht aus, bis er das Recht zu Sieg geführt.',
        21: 'Und auf seinen Namen werden die Völker hoffen.',
        22: 'Da wurde ein Besessener zu ihm gebracht, der war blind und stumm. Und er heilte ihn, so daß der Stumme redete und sah.',
        23: 'Da waren die Leute alle außer sich und sprachen: "Ist der etwa Davids Sohn?"',
        24: 'Als aber die Pharisäer davon hörten, sagten sie: "Nur im Bunde mit Beelzebul, dem Obersten der bösen Geister, treibt er die Teufel aus."',
        25: 'Er aber durchschaute ihre Gedanken und sprach zu ihnen: "Jedes Reich, das in sich selbst uneins ist, das fällt in Trümmer; und jede Stadt oder jedes Haus, das in sich selbst uneins ist, kann nicht bestehen.',
        26: 'Treibt nun der Satan den Satan aus, so ist er ja mit sich selbst im Streit: wie sollte da sein Reich bestehen können?',
        27: 'Treibe ich aber im Bunde mit Beelzebul die bösen Geister aus, mit wessen Hilfe treiben sie denn eure Anhänger aus? Sie werden darum eure Richter sein!',
        28: 'Treibe ich aber durch Gottes Geist die bösen Geister aus, so ist ja Gottes Königreich zu euch gekommen.',
        29: 'Oder wie kann jemand in das Haus eines starken Kriegsmannes dringen und ihm seinen Hausrat rauben, wenn er nicht zuvor den Starken bindet? Erst dann kann er sein Haus berauben.',
        30: 'Wer nicht mit mir ist, der ist gegen mich; und wer nicht mit mir sammelt, der zerstreut.',
        31: 'Darum sage ich euch: Jede Sünde und Lästerung wird den Menschen vergeben, die Lästerung des Geistes aber wird nicht vergeben.',
        32: 'Wer ein Wort sagt gegen den Menschensohn, dem wird vergeben. Wer aber wider den Heiligen Geist redet, der findet keine Vergebung: weder in dieser Weltzeit noch in der zukünftigen.',
        33: 'Erklärt ihr den Baum für gut, so müßt ihr auch seine Frucht für gut halten. Erklärt ihr aber den Baum für schädlich, so müßt ihr auch seine Frucht für schädlich halten. Denn an der Frucht erkennt man den Baum.',
        34: 'Ihr Schlangenbrut! wie könnt ihr Gutes reden, da ihr böse seid? Denn des Mundes Worte fließen aus des Herzens Quell.',
        35: 'Ein guter Mensch entnimmt aus seiner guten Vorratskammer Gutes; ein böser Mensch entnimmt aus seiner bösen Vorratskammer Böses.',
        36: 'Ich versichere euch aber: Von jedem bösen Worte, das die Menschen reden, müssen sie am Tage des Gerichtes Rechenschaft geben.',
        37: 'Denn nach deinen Worten sollst du freigesprochen und nach deinen Worten sollst du verurteilt werden."',
        38: 'Da redeten ihn einige Schriftgelehrte und Pharisäer an und sprachen: "Meister, wir wünschen von dir ein Zeichen zu sehen."',
        39: 'Er antwortete ihnen: "Ein böses, gottvergessenes Geschlecht begehrt ein Zeichen. Es soll ihm aber kein anderes Zeichen gegeben werden als das Zeichen des Propheten Jona.',
        40: 'Denn wie Jona drei Tage und drei Nächte in des Riesenfisches Leib gewesen ist, so wird auch der Menschensohn drei Tage und drei Nächte im Schoß der Erde sein.',
        41: 'Die Leute aus Ninive werden zugleich mit diesen Geschlecht vor Gericht erscheinen und es verurteilen; denn sie bekehrten sich bei Jonas Predigt. Und hier steht doch einer, der größer ist als Jona!',
        42: 'Die Königin aus Süden wird zugleich mit diesem Geschlecht vor Gericht erscheinen und es verurteilen; denn sie kam vom Ende der Erde, um Salomos Weisheit zu hören. Und hier steht doch einer, der größer ist als Salomo!',
        43: 'Ist der unreine Geist von einem Menschen ausgefahren, so wandert er durch Wüsten: er sucht dort eine Ruhstatt und findet keine.',
        44: "Dann spricht er: 'Ich will zurückgehen in mein Haus, das ich verlassen habe.' Und kommt er dann, so findet er es leer, gefegt und wohlgeschmückt.",
        45: 'Nun geht er hin und holt noch sieben andere Geister, die schlimmer sind als er: die ziehen ein und wohnen dort. So wird\'s mit einem solchen Menschen am Ende ärger als zuvor. Ganz ebenso wird es auch gehen mit diesem bösen Geschlecht."',
        46: 'Als er noch zum dem Volke redete, siehe, da standen seine Mutter und seine Brüder draußen und wünschten ihn zu sprechen.',
        48: 'Er aber antwortete dem, der ihm dies meldete: "Wer ist meine Mutter, und wer sind meine Brüder?"',
        49: 'Dann wies er mit ausgestreckter Hand auf seine Jünger und sprach: "Da seht meine Mutter und meine Brüder!',
        50: 'Denn wer den Willen meines Vaters im Himmel tut, der ist mir Bruder, Schwester und Mutter."',
    },
    13: {
        1: 'An jenem Tage ging Jesus aus seinem Hause und setzte sich an den Strand des Sees.',
        2: 'Da sammelte sich eine große Schar um ihn. Deshalb trat er in einen Fischerkahn und setzte sich dort nieder, während das ganze Volk am Ufer stand.',
        3: 'Und er redete zu ihnen vielerlei durch Gleichnisse und sprach:',
        4: '"Ein Sämann ging aus zu säen. Beim Säen fielen einige Körner an den Weg. Da kamen die Vögel und pickten sie auf.',
        5: 'Andere Körner fielen auf steinigen Grund, wo sie nicht viel Erde hatten. Dort schossen sie schnell in den Halm, weil es der Erdschicht an Tiefe fehlte.',
        6: 'Als dann die Sonne heiß schien, litten die Halme von ihrer Glut; und weil sie nicht Wurzel hatten, verdorrten sie.',
        7: 'Andere Körner fielen dahin, wo Dornen wuchsen. Da schossen die Dornen auf und erstickten die Saat.',
        8: 'Andere Körner fielen auf guten Boden und brachten Frucht: hundertfältig, sechzigfältig, dreißigfältig.',
        9: 'Wer Ohren hat, der höre!"',
        10: 'Da traten seine Jünger zu ihm und sprachen: "Warum redest du zu ihnen in Gleichnissen?"',
        11: 'Er antwortete: "Weil euch die Fähigkeit verliehen ist, in die Geheimnisse des Königreichs der Himmel einzudringen, jenen aber nicht',
        12: 'Denn wer (viel) hat, der soll noch mehr empfangen, daß er die Fülle habe; doch wer nur wenig hat, dem soll sogar das wenige genommen werden.',
        13: 'Gerade deshalb rede ich zu ihnen in Gleichnissen, weil sie trotz ihrer Augen nicht sehen und trotz ihrer Ohren nicht hören und verstehen.',
        14: 'So erfüllt sich an ihnen die Weissagung Jesajas: Hören sollt ihr und nicht verstehen, sehen und nicht erkennen,',
        15: 'denn dieses Volkes Herz ist unempfänglich, ihre Ohren hören schwer, und ihre Augen haben sie verschlossen. (So können sie nicht sehen mit ihren Augen, mit ihren Ohren können sie nicht hören, mit ihrem Herzen nicht verstehen und sich bekehren, daß ich sie heile.)',
        16: 'Glückselig aber sind eure Augen, weil sie sehen, und eure Ohren, weil sie hören.',
        17: 'Denn viele Propheten und Gerechte — das versichere ich euch — haben sich gesehnt, zu schauen was ihr seht, und haben es nicht geschaut, und zu hören, was ihr hört, und haben es nicht gehört.',
        18: 'Euch nun will ich das Gleichnis vom Sämann deuten:',
        19: 'Hört einer das Wort vom Königreich und hat kein Verständnis dafür, so kommt der Böse und nimmt den Samen weg, der in sein Herz gesät war: bei solchem fällt der Same an den Weg.',
        20: 'Was auf steinigen Boden fällt, das bedeutet einen, der das Wort hört und es sogleich mit Freuden aufnimmt;',
        21: 'es schlägt aber nicht Wurzel in ihm, sondern er hält nur eine Zeitlang aus. Kommen Trübsal und Verfolgung um des Wortes willen, so wird er bald im Glauben wankend.',
        22: 'Was dahin fällt, wo Dornen wachsen, das bedeutet einen Hörer, bei dem die Sorge um die irdischen Dinge und der verführerische Reiz des Reichtums das Wort zu ersticken, so daß es fruchtlos bleibt.',
        23: 'Was aber auf guten Boten fällt, dies bedeutete einen Hörer, der für das Verständnis hat: der bringt dann Frucht, der eine hundertfältig, der andere sechzigfältig, der dritte dreißigfältig.',
        24: 'Ein anderes Gleichnis trug er ihnen vor, indem er sprach: "Das Königreich der Himmel gleicht einem Menschen, der guten Samen auf seinen Acker säte.',
        25: 'Als aber die Leute schliefen, kam sein Feind: der streute Unkrautsamen mitten unter den Weizen und ging dann weg.',
        26: 'Als nun die Saat aufging und Frucht ansetzte, zeigte sich auch das Unkraut.',
        27: "Da kamen die Knechte zum Hausherrn und sprachen: 'Herr, hast du nicht guten Samen auf deinen Acker gesät? Woher hat er denn das Unkraut?'",
        28: "Er antwortete ihnen: 'Das hat ein Feind getan.' Da fragten ihn seine Knechte: 'Sollen wir nun hingehen und es ausjäten?'",
        29: "Er sagte: 'Nein; ihr würdet sonst beim Sammeln des Unkrauts auch den Weizen mit ausreißen.",
        30: 'Laßt beides miteinander wachsen bis zur Ernte. Zur Erntezeit will ich dann den Schnittern sagen: Sammelt zuerst das Unkraut und bindet es in Bündel zum Verbrennen, den Weizen aber bringt in meinen Speicher!\'"',
        31: 'Ein anderes Gleichnis trug er ihnen vor: "Das Königreich der Himmel ist einem Senfkorn gleich, das einer nimmt und auf seinen Acker sät.',
        32: 'Es ist das kleinste unter allen Samenkörnern. Ist es aber ausgewachsen, so ist es größer als die anderen Gartenkräuter und wird sogar ein Baum, so daß die Vögel des Himmels kommen und in seinen Zweigen nisten."',
        33: 'Ein anderes Gleichnis redete er zu ihnen: "Das Königreich der Himmel gleicht einem Sauerteig, den eine Frau nimmt und ihn so lange in drei Scheffel Weizenmehl knetet, bis der ganze Teig durchsäuert ist."',
        34: 'Dies alles redete Jesus zu dem Volk in Gleichnissen, und ohne Gleichnis redete er nichts zu ihnen, damit sich der Ausspruch des Propheten erfülle: Ich will meinen Mund zu Gleichnisreden öffnen; ich will verkünden, was seit Anbeginn der Welt verhüllt gewesen ist.',
        36: 'Dann entließ er die Volksmenge und kehrte in sein Haus zurück. Da traten seine Jünger zu ihm und sprachen: "Deute uns das Gleichnis vom Unkraut auf dem Acker!"',
        37: 'Er antwortete: "Der Sämann, der den guten Samen ausstreut, ist der Menschensohn.',
        38: 'Der Acker ist die Welt. Der gute Same sind die Kinder des Königreichs. Das Unkraut sind die Kinder des Bösen.',
        39: 'Der Feind, der das Unkraut sät, ist der Teufel. Die Ernte ist das Ende dieser Weltzeit. Die Schnitter sind die Engel.',
        40: 'Wie man nun das Unkraut sammelt und mit Feuer verbrennt, so wird es auch am Ende dieser Weltzeit gehen.',
        41: 'Der Menschensohn wird seine Engel senden; die sollen aus seinem Königreich alle Verführer und Übeltäter sammeln',
        42: 'und sie in den Feuerofen werfen: dort wird lautes Klagen und Zähneknirschen sein.',
        43: 'Dann werden die Gerechten hervorleuchten wie die Sonne in ihres Vaters Königreich. Wer Ohren hat, der höre!',
        44: 'Das Königreich der Himmel gleicht einem Schatz, der in einem Ackerfeld vergraben liegt. Den findet einer, deckt ihn wieder zu (mit Erde) und geht dann hin in seiner Freude, verkauft all seine Habe und kauft den Acker.',
        45: 'Weiter gleicht das Königreich der Himmel einem Händler, der wertvolle Perlen sucht.',
        46: 'Hat er aber eine besonders wertvolle Perle gefunden, so geht er hin, verkauft all seine Habe und kauft die Perle.',
        47: 'Weiter gleicht das Königreich der Himmel einem Schleppnetz, das ins Meer geworfen wird und womit man allerlei Fische fängt.',
        48: 'Ist es voll, so zieht man es ans Ufer. Dort setzen sich die Fischer und sammeln die guten Fische in Gefäße, die schlechten aber werfen sie weg.',
        49: 'So wird es auch am Ende dieser Weltzeit sein. Die Engel werden ausgehen, sie werden die Bösen von den Gerechten scheiden',
        50: 'und sie in den Feuerofen werfen: dort wird lautes Klagen und Zähneknirschen sein.',
        51: 'Hab ihr dies alles verstanden?"',
        52: 'Sie antworteten ihm: "Jawohl!" Dann fuhr er fort: "Darum gilt hier der Satz: Jeder Schriftgelehrte, der für den Dienst des Königreichs der Himmel ausgebildet worden ist, gleicht einem Hausherrn, der aus seinem Vorrat Neues und Altes mitteilt."',
        53: 'Als Jesus diese Gleichnisreden vollendet hatte, zog er von dort weg',
        54: 'und kam in seine Vaterstadt. Dort lehrte er die Leute in ihrem Versammlungshaus, so daß sie voller Staunen sprachen: "Woher hat der Mann solche Weisheit und Wunderkräfte?',
        55: 'Ist er nicht des Tischlers Sohn? Heißt nicht seine Mutter Maria? Sind nicht Jakobus, Josef, Simon und Judas seine Brüder?',
        56: 'Wohnen nicht auch seine Schwestern alle hier bei uns? Woher hat er denn dies alles?"',
        57: 'Und sie wollten nichts von ihm wissen. Da sprach Jesus zu ihnen: "Ein Prophet gilt nirgends weniger als in seiner Heimat und im Kreise seiner Hausgenossen."',
        58: 'Er tat dort auch nur wenig Wunder, weil sie nicht glaubten.',
    },
    14: {
        1: 'Um jene Zeit hörte der Vierfürst Herodes von Jesus,',
        2: 'und er sprach zu seinen Hofleuten: "Das ist Johannes der Täufer! Der ist von den Toten auferstanden, darum sind die Wunderkräfte in ihm wirksam."',
        3: 'Herodes hatte nämlich damals Johannes ergreifen, mit Ketten binden und gefangensetzen lassen wegen Herodias, der Frau seines Bruders Philippus.',
        4: 'Denn Johannes hatte ihm gesagt: "Du darfst sie nicht zur Frau haben."',
        5: 'Er hätte ihn nun gern getötet; aber er scheute sich vor dem Volke, denn das hielt ihn für einen Propheten.',
        6: 'Da geschah es bei der Geburtstagsfeier des Herodes, daß die Tochter der Herodias vor den Gästen tanzte. Das gefiel Herodes so sehr,',
        7: 'daß er ihr eidlich versprach, er wolle ihr geben, um was sie bitte.',
        8: 'Da sprach sie, von ihrer Mutter dazu angestiftet: "Gib mir hier auf einer Schüssel das Haupt Johannes des Täufers!"',
        9: "Darüber ward der König betrübt. Doch um des Eides und der Tischgenossen willen befahl er's ihr zu geben.",
        10: 'So sandte er denn hin und ließ Johannes in seinem Kerker enthaupten.',
        11: 'Sein Haupt ward dann auf einer Schüssel hergebracht und dem Mädchen gegeben; die brachte es ihrer Mutter.',
        12: 'Und seine Jünger kamen, holten seinen Leichnam und begruben ihn. Dann gingen sie hin und gaben Jesus Bericht.',
        13: 'Auf diese Kunde entfernte sich Jesus von dort in einem Boot nach einer unbewohnten Gegend, um allein zu sein. Aber die Leute hörten davon und gingen ihm zu Fuß aus den Städten nach.',
        14: 'Als nun Jesus aus dem Fahrzeug stieg, empfand er tiefes Mitleid bei dem Anblick der großen Menge, und er heilte ihre Kranken.',
        15: 'Am Abend traten seine Jünger zu ihm und sprachen: "Die Gegend hier ist unbewohnt, und es ist schon spät. Laß deshalb die Leute ziehen, damit sie in die nächsten Dörfer gehen und sich Lebensmittel kaufen."',
        16: 'Jesus antwortete ihnen: "Sie brauchen nicht zu gehen; gebt ihr ihnen zu essen!"',
        17: 'Sie erwiderten ihm: "Wir haben hier nichts weiter als fünf Brote und zwei Fische."',
        18: 'Er sprach: "Bringt sie mir her!"',
        19: 'Und er ließ die Leute sich auf dem Gras lagern. Nun nahm er die fünf Brote und die beiden Fische, sah auf zum Himmel und sprach den Lobpreis. Dann brach er die Brote und gab sie seinen Jüngern, die Jünger aber reichten sie den Leuten.',
        20: 'So aßen alle und wurden satt. Die übriggebliebenen Brocken hob man vom Boden auf: zwölf große Körbe voll.',
        21: 'Es hatten aber ungefähr fünftausend Mann gegessen, ohne die Frauen und Kinder.',
        22: 'Nun drängte er seine Jünger, sofort in das Boot zu gehen und an das andere Ufer vorauszufahren während er das Volk entlassen wollte.',
        23: 'Als dies geschehen, ging er auf die Bergeshöhe, um in der Einsamkeit zu beten. Beim Eintritt der Dunkelheit war er dort allein.',
        24: 'Inzwischen war das Boot schon mitten auf dem See und mußte heftig mit den Wellen kämpfen, denn es fuhr gegen den Wind.',
        25: 'Da, in der vierten Nachtwache, kam er, über den See hingehend, auf sie zu.',
        26: 'Als ihn die Jünger so auf dem See wandeln sahen, waren sie entsetzt; denn sie dachten, es wäre ein Gespenst, und sie schrien laut vor Furcht.',
        27: 'Aber alsbald rief ihnen Jesus zu: "Seid getrost, ich bin\'s, fürchtet euch nicht!"',
        28: 'Da antwortete ihm Petrus: "Herr, bist du es, so laß mich auf dem Wasser zu dir kommen."',
        29: 'Er sprach: "Komm!" Da stieg Petrus aus dem Boot und ging auf dem Wasser zu Jesus hin.',
        30: 'Als er aber den starken Wind spürte, ward ihm bange, und er begann zu sinken. Da schrie er auf: "Herr, hilf mir!"',
        31: 'Sofort streckte Jesus seine Hand aus, ergriff ihn und sprach zu ihm: "Du Kleingläubiger, warum hast du gezweifelt?"',
        32: 'Dann stiegen sie beide in das Boot, und er Wind legte sich.',
        33: 'Die anderen aber, die im Boot waren, fielen vor ihm nieder und sprachen: "Du bist wahrhaftig Gottes Sohn!"',
        34: 'Als sie die Überfahrt vollendet hatten, stiegen sie ans Land und kamen nach Genezaret.',
        35: 'Sobald ihn die Bewohner dieser Gegend erkannten, schickten sie Boten in den ganzen Umkreis.',
        36: 'Da brachte man ihm alle Kranken und bat ihn, daß sie nur die Quaste seines Mantels berühren dürften. Und alle, die sie berührten, wurden gesund.',
    },
    15: {
        1: 'Dann traten zu Jesus Schriftgelehrte und Pharisäer, die aus Jerusalem gekommen waren, und sprachen:',
        2: '"Warum übertreten deine Jünger Vorschriften, die uns die Alten überliefert haben? Sie waschen sich ja vor der Mahlzeit die Hände nicht."',
        3: 'Er antwortete ihnen: "Warum übertretet ihr denn euern Vorschriften zuliebe Gottes Gebot?',
        4: 'Gott hat doch gesagt: Ehre deinen Vater und deine Mutter! und: wer Vater oder Mutter schmäht, der soll des Todes sterben.',
        5: "Ihr aber behauptet: Wer zum Vater oder zur Mutter spricht: 'Ich stifte für den Tempelschatz, was ich dir sonst zum Unterhalt gegeben hätte' — der braucht Vater oder Mutter nicht zu ehren.",
        6: 'So setzt ihr eurer Satzung zuliebe Gottes Gesetz außer Kraft.',
        7: 'Ihr Heuchler! Treffend hat Jesaja von euch geweissagt:',
        8: 'Dies Volk ehrt mich mit den Lippen, aber ihr Herz ist fern von mir.',
        9: 'Ihr Gottesdienst ist wertlos, denn sie verkünden Lehren, die nichts als Menschensatzung sind."',
        10: 'Dann rief er das Volk herbei und sprach zu ihnen: "Hört und versteht es!',
        11: 'Nicht das macht den Menschen unrein, was zum Mund eingeht; sondern was zum Munde ausgeht, das macht den Menschen unrein."',
        12: 'Da traten seine Jünger zu ihm und sprachen: "Weißt du, daß die Pharisäer über dein Wort, das sie haben hören müssen, entrüstet gewesen sind?"',
        13: 'Er antwortete: "Jede Pflanze, die mein himmlischer Vater nicht gepflanzt hat, soll ausgerottet werden.',
        14: 'Laß sie! Sie sind blinde Blindenführer. Wenn aber ein Blinder den anderen führt, so fallen sie beide in die Grube."',
        15: 'Da nahm Petrus das Wort und sprach zu ihm: "Deute uns dies Gleichnis!"',
        16: 'Er erwiderte: "Seid ihr denn auch noch immer so unverständig?',
        17: 'Seht ihr nicht ein, daß alles, was zum Munde eingeht, in den Magen kommt und dann durch den Darm ausgeschieden wird?',
        18: 'Was aber zum Munde ausgeht, das kommt aus dem Herzen, und das macht den Menschen unrein.',
        19: 'Denn aus dem Herzen kommen böse Gedanken: Mord, Ehebruch, Unzucht, Diebstahl, falsches Zeugnis und Verleumdung.',
        20: 'Hierdurch wird der Mensch verunreinigt. Aber mit ungewaschenen Händen essen, das macht den Menschen nicht unrein."',
        21: 'Dann verließ Jesus jene Gegend und begab sich in das Gebiet von Tyrus und Sidon.',
        22: 'Und sieh, eine Kananiterin aus jener Landschaft kam zu ihm; die fing an zu rufen: "Herr, Sohn Davids, erbarme dich mein! Meine Tochter wird von einem bösen Geist arg gequält."',
        23: 'Er aber erwiderte ihr kein einziges Wort. Da traten seine Jünger zu ihm mit der Bitte: "Fertige sie doch ab! Sie schreit ja hinter uns her."',
        24: 'Er aber antwortete: "Ich bin nur zu den verirrten Schafen des Hauses Israel gesandt."',
        25: 'Da kam die Frau, fiel ihm zu Füßen und bat: "Herr, hilf mir!"',
        26: 'Er aber erwiderte: "Es wäre nicht recht, den Kindern das Brot zu nehmen und es den Hündchen hinzuwerfen."',
        27: 'Sie sprach: "Gewiß, Herr! Denn die Hündchen dürfen ja nur die Brocken fressen, die von ihrer Herren Tische fallen."',
        28: 'Da antwortete ihr Jesus: "O Weib, dein Glaube ist groß! Dir geschehe, wie du willst." Und zu der Stunde ward ihre Tochter gesund.',
        29: 'Dann verließ Jesus die Gegend und kam an das Ufer des Galiläischen Sees: er ging auf die Berghöhe und blieb dort.',
        30: 'Da kamen viele Leute zu ihm; die brachten Lahme, Blinde, Stumme Krüppel und viele andere Kranke und legten sie zu seinen Füßen nieder. Und er heilte sie.',
        31: 'Da wunderten sich die Leute, als sie sahen, wie die Stummen redeten, die Krüppel genasen, die Lahmen gingen und die Blinden sahen. Und sie priesen den Gott Israels.',
        32: 'Da rief Jesus seine Jünger zu sich und sprach: "Mich jammert der Leute, denn sie sind nun schon drei Tage bei mir und haben nichts mehr zu essen; und hungrig mag ich sie nicht gehen lassen, sonst könnten sie unterwegs ermattet zusammenbrechen."',
        33: 'Seine Jünger sprachen zu ihm: "Woher sollen wir in dieser unbewohnten Gegend Brot genug bekommen, um so viele Menschen zu sättigen?"',
        34: 'Jesus fragte sie: Wieviel Brote habt ihr denn?" Sie sprachen: "Sieben und ein paar kleine Fische."',
        35: 'Da ließ er die ganze Schar sich auf die Erde lagern.',
        36: 'Dann nahm er die sieben Brote und die Fische, sprach das Dankgebet, brach sie und gab sie den Jüngern, die dann die Leute speisten.',
        37: 'So aßen alle und wurden satt. Die übriggebliebenen Brocken hob man vom Boden auf: sieben kleine Körbe voll.',
        38: 'Es hatten aber etwa viertausend Mann gegessen, ohne die Frauen und Kinder.',
        39: 'Dann ließ er die Menge gehen, stieg in sein Boot und kam in das Gebiet von Magadan.',
    },
    16: {
        1: 'Dort traten Pharisäer und Sadduzäer an ihn heran, um ihn auszuhorchen, und forderten ihn auf, er möge sie ein Wunderzeichen vom Himmel sehen lassen.',
        2: 'Er aber erwiderte ihnen: "(Am Abend sagt ihr: \'Es wird gutes Wetter, denn der Himmel ist gerötet\',',
        3: "und frühmorgens: 'Heute wird es stürmisch, denn der Himmel ist rötlich und trübe.' Des Himmels Aussehen wißt ihr zu deuten, und die Zeichen der Zeit versteht ihr nicht?)",
        4: 'Ein böses, gottvergessenes Geschlecht begehrt ein Zeichen; es wird ihm aber kein anderes Zeichen gegeben werden als das Zeichen des Propheten Jona." Damit wandte er sich von ihnen und ging weg.',
        5: 'Als die Jünger an das andere Ufer kamen, entdeckten sie, daß sie vergessen hatten, Brot mitzunehmen.',
        6: 'Da sprach Jesus zu ihnen: "Habt acht und hütet euch vor dem Sauerteig der Pharisäer und Sadduzäer!"',
        7: 'Die Jünger dachten bei sich und sprachen es auch gegeneinander aus: "Das sagt er, weil wir kein Brot mitgenommen haben."',
        8: 'Jesus merkte das und sprach: "Ihr Kleingläubigen, was macht ihr euch Gedanken darüber, daß ihr kein Brot mithabt?',
        9: "Fehlt's euch denn immer noch an Einsicht? Denkt ihr nicht an die fünf Brote für die Fünftausend, und wieviel große Körbe voll ihr noch mitgenommen habt?",
        10: 'Und denkt ihr nicht an die sieben Brote für die Viertausend, und wieviel kleine Körbe voll ihr noch mitgenommen habt?',
        11: 'Seht ihr denn nicht ein, daß ich bei meinen Worten nicht an Brot gedacht habe? Hütet euch aber vor dem Sauerteig der Pharisäer und Sadduzäer!"',
        12: 'Nun erst verstanden sie, daß er nicht gemeint hatte, sie sollten sich hüten vor dem Sauerteig der Brote, sondern vor der Lehre der Pharisäer und Sadduzäer.',
        13: 'Hierauf kam Jesus in das Gebiet von Cäsarea Philippi. Dort frage er seine Jünger: "Wofür halten die Leute den Menschensohn?"',
        14: 'Sie sprachen: "Die einen halten dich für Johannes den Täufer, die anderen für Elia, wieder andere für Jeremia oder sonst einen der Propheten."',
        15: 'Da sprach er zu ihnen: "Für wen haltet ihr mich denn?"',
        16: 'Simon Petrus antwortete: "Du bist der Messias, der Sohn Gottes, des Lebendigen."',
        17: 'Da erwiderte ihm Jesus: "Selig bist du, Simon, Jonas Sohn; denn nicht ein sterblicher Mensch von Fleisch und Blut hat dir dies offenbart, sondern mein Vater im Himmel.',
        18: 'Und ich sage dir: Du bist Petrus, und im Anschluß an diesen Stein will ich das Haus meiner Kirche bauen, und des Totenreiches Tore sollen sie nicht bezwingen.',
        19: 'Ich will dir die Schlüssel des Königreichs der Himmel geben: Was du auf Erden binden wirst, das soll im Himmel gebunden sein; und was du auf Erden lösen wirst, das soll im Himmel gelöst sein."',
        20: 'Dann schärfte er seinen Jüngern ein, sie sollten niemand sagen, daß er der Messias sei.',
        21: 'Von der Zeit an begann Jesus seinen Jüngern darzulegen: er müsse nach Jerusalem gehen und dort viel leiden von den Ältesten, Hohenpriestern und Schriftgelehrten; ja er müsse den Tod erdulden, aber am dritten Tag wieder auferstehen.',
        22: 'Da nahm ihn Petrus beiseite, begann ihm ernste Vorstellungen zu machen und sprach: "Gott bewahre, Herr! Das darf dir nimmermehr geschehen!"',
        23: 'Er aber wandte sich weg und sprach zu Petrus: "Mir aus den Augen, Satan! Du willst mich verführen! Denn du denkst nicht göttlich, sondern menschlich."',
        24: 'Dann sprach Jesus zu seinen Jüngern: "Wer mein Nachfolger sein will, der verleugne sich selbst und nehme sein Kreuz auf sich und folge mir.',
        25: "Denn wer sein Leben retten will, der wird's verlieren; wer aber sein Leben um meinetwillen verliert, der wird es gewinnen.",
        26: 'Was nützt es dem Menschen, wenn er die ganze Welt gewinnt und dabei sein Seelenheil verliert? Oder welchen Preis kann jemand zahlen, um sich damit sein Seelenheil zu erkaufen?',
        27: 'Denn der Menschensohn wird kommen in seines Vaters Herrlichkeit und in Begleitung seiner Engel; dann wird er einem jeden nach seinem Tun vergelten. Wahrlich, ich sage euch: Einige von denen, die hier stehen, sollen den Tod nicht schmecken, ehe sie den Menschensohn in seiner Königsherrschaft haben kommen sehen."',
    },
    17: {
        1: 'Sechs Tage später nahm Jesus Petrus und das Brüderpaar Jakobus und Johannes mit sich und führte sie allein auf einen hohen Berg.',
        2: 'Dort trat vor ihren Augen in seinem Äußeren eine Wandlung ein: sein Antlitz strahlte wie die Sonne, und seine Kleider glänzten hell wie das Licht.',
        3: 'Und siehe, Mose und Elia erschienen ihnen, die hatten ein Gespräch mit ihm.',
        4: 'Da nahm Petrus das Wort und sprach zu Jesus: "Herr, es trifft sich gut, daß wir hier sind. Wenn du erlaubst, so will ich hier drei Hütten bauen, für dich eine, für Mose eine und für Elia eine."',
        5: 'Während er noch redete, umhüllte sie plötzlich eine lichthelle Wolke, und aus der Wolke rief eine Stimme: "Dies ist mein geliebter Sohn, den ich erkoren; auf den hört!"',
        6: 'Bei diesen Worten fielen die Jünger tieferschrocken auf ihr Angesicht.',
        7: 'Jesus aber trat zu ihnen rührte sie an und sprach: "Steht auf und fürchtet euch nicht!"',
        8: 'Da schlugen sie ihre Augen auf und sahen niemand als Jesus allein.',
        9: 'Als sie vom Berg hinabgingen, gebot ihnen Jesus: "Sagt niemand etwas von dem, was ihr gesehen, bis der Menschensohn von den Toten auferstanden ist."',
        10: 'Da fragten ihn die Jünger: "Warum behaupten denn die Schriftgelehrten, Elia müsse vorher kommen?"',
        11: 'Er antwortete: "Gewiß! Elia soll kommen und alles in Ordnung bringen.',
        12: 'Aber ich versichere euch: Elisa ist schon gekommen; doch sie haben ihn nicht anerkannt, sondern ihren Mutwillen an ihm geübt. Ebenso wird auch der Menschensohn von ihnen leiden müssen."',
        13: 'Da verstanden die Jünger, daß er von Johannes dem Täufer zu ihnen geredet hatte.',
        14: 'Als sie nun zu dem Volkshaufen kamen, trat ein Mann zu ihm, der bat in fußfällig:',
        15: '"Herr, erbarme dich meines Sohnes! Er ist mondsüchtig und hat schwer zu leiden: er fällt oft ins Feuer und ins Wasser.',
        16: 'Ich habe ihn zu deinen Jüngern gebracht, aber sie haben ihn nicht heilen können."',
        17: 'Jesus antwortete: "Ihr ungläubige und verkehrte Art, wie lange soll ich bei euch sein? Wie lange soll ich euch ertragen? Bringt ihn mir her!"',
        18: 'Und Jesus bedrohte den bösen Geist: da fuhr er aus von dem Knaben, so daß er von Stund an gesund wurde.',
        19: 'Darauf traten die Jünger zu Jesus, als er mit ihnen allein war, und fragten: "Warum haben wir den bösen Geist nicht austreiben können?"',
        20: 'Er antwortete ihnen: "Weil ihr so wenig Glauben habt. Denn ich versichere euch: Hättet ihr nur Glauben wie ein Senfkorn, so könntet ihr zu dem Berg da sprechen: \'Rücke von hier weg dorthin!\' und er würde es tun; ja nichts wäre euch unmöglich."',
        22: 'Als sie zusammen in Galiläa wanderten, sprach Jesus zu ihnen: "Der Menschensohn wird in der Menschen Hände überliefert werden,',
        23: 'und sie werden ihn töten; aber am dritten Tag wird er wieder auferstehen." Da wurden sie sehr betrübt.',
        24: 'Nach ihrer Ankunft in Kapernaum traten die Einnehmer der Tempelsteuer zu Petrus und fragten ihn: "Entrichtet euer Meister die Tempelsteuer nicht?"',
        25: 'Er antwortete: "Jawohl!" Dann ging er in das Haus (wo Jesus wohnte). Dort fragte ihn Jesus, noch ehe Petrus von dem Vorfall geredet hatte: "Was meinst du, Simon? Von wem erheben die Könige dieser Erde Zoll oder Steuer? von ihren Söhnen oder von ihren Untertanen?"',
        26: '"Von ihren Untertanen", erwiderte er. Da sprach Jesus zu ihm: "Mithin sind die Söhne steuerfrei.',
        27: 'Damit wir aber den Leuten keinen Anstoß geben, so geh an den See und wirf die Angel aus! Den ersten Fisch, der anbeißt, den zieh empor und öffne ihm das Maul! Da wirst du eine Silbermünze finden; die nimm und gib sie ihnen für mich und dich!"',
    },
    18: {
        1: 'Zu jener Stunde traten die Jünger zu Jesus und fragten ihn: "Wer ist wohl der Größte im Königreich der Himmel?"',
        2: 'Da rief er ein kleines Kind herbei, stellte es mitten unter sie',
        3: 'und sprach: "Wahrlich, ich sage euch: Wenn ihr nicht umkehrt und wie die kleinen Kinder werdet, so kommt ihr sicher nicht ins Königreich der Himmel.',
        4: 'Wer sich nun erniedrigt wie dies Kind hier, der ist der Größte im Königreich der Himmel.',
        5: 'Und wer ein solches Kind aufnimmt, weil es meinen Namen bekennt, der nimmt mich auf.',
        6: 'Wer aber eins von den kleinen Kindern hier, die an mich glauben, zur Sünde verführt, für den wäre es besser gewesen, man hätte ihm vorher einen großen Mühlstein um den Hals gehängt und ihn versenkt im Meer, wo es am tiefsten ist.',
        7: 'Weh der Welt, die voll Verführung ist! Verführungen sind zwar unvermeidlich; doch weh dem Menschen, durch den Verführung kommt!',
        8: 'Wenn dich aber deine Hand oder dein Fuß zur Sünde reizt, haue sie ab und wirf sie weg! Es ist besser für dich, du gehst verstümmelt oder hinkend ins Leben ein, als daß du zwei Hände oder zwei Füße hast und ins ewige Feuer geworfen wirst.',
        9: 'Und wenn dich dein Auge zur Sünde reizt, reiß es aus und wirf es weg! Es ist besser für dich, du gehst einäugig ins Leben ein, als daß du zwei Augen hast und ins höllische Feuer geworfen wirst.',
        10: 'Nehmt euch in acht, eins dieser Kinder geringzuschätzen! Denn ich sage euch: Ihre Engel haben im Himmel allzeit freien Zutritt zu meinem himmlischen Vater.',
        12: 'Was meint ihr? Wenn jemand hundert Schafe hat und eins davon verirrt sich: läßt er dann nicht die anderen neunundneunzig allein in den Bergen weiden und geht hin, um das verirrte zu suchen?',
        13: "Und glückt's ihm, es zu finden, ich versichere euch: er freut sich mehr darüber als über die neunundneunzig, die sich nicht verirrt.",
        14: 'So will auch euer Vater im Himmel nicht, daß eins dieser Kinder verlorengehe.',
        15: 'Hat sich dein Bruder an dir versündigt, so geh zu ihm und stelle ihm unter vier Augen sein Unrecht vor. Hört er auf dich, so hast du deinen Bruder gewonnen.',
        16: 'Hört er nicht, so geh nochmals zu ihm in Begleitung eines oder zweier Brüder, damit jedes Wort, das gesprochen wird, durch zwei oder drei Zeugen festgestellt werden könne.',
        17: 'Will er aber nicht auf diese Brüder hören, so bring die Sache vor die Gemeinde. Und hört er auch auf die Gemeinde nicht, dann sieh ihn an wie einen Heiden und Zöllner.',
        18: 'Wahrlich, ich sage euch: Was ihr auf Erden bindet, das soll im Himmel gebunden sein; und was ihr auf Erden löst, das soll auch im Himmel gelöst sein.',
        19: 'Weiter sage ich euch: Wenn hier auf Erden zwei von euch einig sind, um etwas zu bitten, so soll es ihnen von meinem Vater im Himmel zuteil werden.',
        20: 'Denn wo zwei oder drei in meinem Namen versammelt sind, da bin ich in ihrer Mitte gegenwärtig."',
        21: 'Darauf trat Petrus zu ihm mit der Frage: "Herr, wenn sich mein Bruder gegen mich versündigt, wie oft muß ich ihm dann vergeben? Etwa siebenmal?"',
        22: 'Jesus antwortete ihm: "Ich sage dir: nicht siebenmal, sondern siebzigmal siebenmal.',
        23: 'Darum gleicht das Himmelreich einem König, der mit seinen Dienern abrechnen wollte.',
        24: 'Als er mit der Abrechnung begann, ward ihm einer vorgeführt, der ihm zehntausend Talente schuldig war.',
        25: 'Weil er aber nicht bezahlen konnte, ließ ihn der Herr mit Weib und Kind und all seiner Habe zur Deckung der Schuld verkaufen.',
        26: "Da fiel ihm der Diener zu Füßen und bat: 'Hab nur Geduld mit mir, ich will dir alles bezahlen!'",
        27: 'Da hatte der Herr Erbarmen mit dem Diener: er gab ihn frei, und die Schuld erließ er ihm auch.',
        28: "Beim Hinausgehen traf nun dieser Diener einen anderen, der ihm hundert Silberlinge schuldete. Den packte er an der Gurgel und rief: 'Bezahle mir, was du schuldig bist!'",
        29: "Da warf sich sein Mitdiener vor ihm nieder und bat ihn: 'Hab nur Geduld mit mir, ich will dir's schon bezahlen.'",
        30: 'Aber er wollte nicht, sondern nahm ihn mit sich und ließ ihn ins Gefängnis werfen, bis er seine Schuld bezahlt hätte.',
        31: 'Als das die anderen Diener sahen, wurden sie sehr betrübt; sie gingen zu ihrem Herrn und erzählten ihm alles.',
        32: "Da ließ der Herr den Diener rufen und sprach zu ihm: 'Du Bösewicht! Deine ganze Schuld habe ich dir auf dein Bitten erlassen.",
        33: "Hättest du dich da nicht auch über deinen Mitknecht erbarmen müssen, wie ich mich über dich erbarmt habe?'",
        34: 'Und voll Zorn ließ ihn sein Herr den Folterknechten übergeben, bis er ihm die ganze Schuld bezahlt hätte.',
        35: 'Ebenso wird auch mein himmlischer Vater mit euch verfahren, wenn ihr nicht allesamt von Herzen den Brüdern vergebt."',
    },
    19: {
        1: 'Als Jesus diese Reden beendet hatte, verließ er Galiläa und zog durch das Ostjordanland in das Gebiet von Judäa.',
        2: 'Eine große Volksmenge begleitete ihn, deren Kranke er dort heilte.',
        3: 'Da traten Pharisäer zu ihm; die wollten ihm eine Falle stellen und fragten ihn: "Darf jemand sein Weib aus jedem beliebigen Grund entlassen?"',
        4: 'Er antwortete: "Habt ihr nicht gelesen, daß der Schöpfer im Anfang die Menschen als Mann und Weib geschaffen hat?',
        5: 'Und er hat gesagt: Deshalb wird ein Mann Vater und Mutter verlassen und sich aufs engste mit seinem Weib verbinden, und beide werden eins sein.',
        6: 'Sie sind als nicht mehr zwei, sondern eins. Was nun Gott vereinigt hat, das soll der Mensch nicht trennen!"',
        7: 'Sie sprachen zu ihm: "Warum hat denn Mose geboten, der Mann solle der Frau einen Scheidebrief ausstellen und dürfe sie dann aus seinem Haus entlassen?"',
        8: 'Er antwortete ihnen: "Wegen eurer Herzenshärtigkeit hat euch Mose erlaubt, eure Frauen zu entlassen. Doch anfangs ist es nicht so gewesen.',
        9: 'Ich sage euch aber: "Wer sein Weib aus einem anderen Grund entläßt als wegen Unzucht und eine andere heiratet, der ist ein Ehebrecher. Und wer eine (von ihrem Mann) entlassene Frau zum Weib nimmt, der ist auch ein Ehebrecher."',
        10: 'Da sprachen die Jünger zu ihm: "Wenn es zwischen Mann und Weib so steht, dann ist es besser, nicht zu heiraten."',
        11: 'Er antwortete ihnen: "Nicht jeder ist dazu fähig, sonder der allein, dem es verliehen ist.',
        12: 'Es gibt Ehelose, die von Geburt an zur Ehe untüchtig sind, und es gibt Ehelose, denen durch Menschen die Fähigkeit zur Ehe genommen worden ist; aber es gibt auch Ehelose, die mit Rücksicht auf das Königreich der Himmel freiwillig auf die Ehe verzichtet haben. Wer dazu fähig ist, der tue es!"',
        13: 'Dann brachte man kleine Kinder zu ihm, damit er ihnen unter Gebet die Hände auflege. Die Jünger aber fuhren die Leute mit rauhen Worten an.',
        14: 'Doch Jesus sprach: "Laßt die kleinen Kinder zu mir kommen und hindert sie nicht daran! Denn gerade ihnen ist das Himmelreich bestimmt."',
        15: 'Dann legte er ihnen die Hände auf und verließ den Ort.',
        16: 'Und siehe, einer trat an ihn heran und fragte: "Meister, was für ein gutes Werk muß ich tun, um das ewige Leben zu erlangen?"',
        17: 'Er antwortete ihm: "Warum fragst du mich nach dem, was gut ist? Nur ein einziger ist gut. Willst du aber zum Leben eingehen, so halte die Gebote."',
        18: 'Er sprach zu ihm: "Welche?" Jesus erwiderte: "Diese: Du sollst nicht morden, nicht ehebrechen, nicht stehlen, nicht falsches Zeugnis ablegen!',
        19: 'Ehre Vater und Mutter! Und: du sollst deinen Nächsten lieben wie dich selbst."',
        20: 'Der Jüngling sprach zu ihm: "Dies alles habe ich treu erfüllt. Was fehlt mir noch?"',
        21: 'Da antwortete ihm Jesus: "Willst du vollkommen sein, so gehe hin, verkaufe deine Habe und gib das Geld den Armen: so wirst du einen Schatz im Himmel haben; dann komm und folge mir!"',
        22: 'Als der Jüngling das hörte, ging er traurig weg, denn er hatte ein großes Vermögen.',
        23: 'Da sprach Jesus zu seinen Jüngern: "Wahrlich, ich sage euch: Ein Reicher kommt nur schwer ins Königreich der Himmel.',
        24: 'Ja ich sage euch: Ein Kamel kommt leichter durch ein Nadelöhr als ein Reicher in Gottes Königreich."',
        25: 'Als die Jünger das hörten, erschraken sie sehr und sprachen: "Ja, wer kann dann überhaupt gerettet werden?"',
        26: 'Jesus aber sah sie an und erwiderte: "Mit menschlicher Kraft ist das zwar nicht möglich; mit Gottes Hilfe aber ist alles möglich."',
        27: 'Da nahm Petrus das Wort und sprach zu ihm: "Sieh, wir haben alles aufgegeben und sind dir nachgefolgt. Welcher Lohn wird uns dafür?"',
        28: 'Jesus antwortete ihnen: "Wahrlich, ich sage euch: Wenn der Menschen zur Zeit der Wiedergeburt auf dem Thron seiner Herrlichkeit sitzt, dann sollt auch ihr, die ihr mir nachgefolgt seid, auf zwölf Thronen sitzen und die zwölf Stämme Israels als Herrscher leiten.',
        29: 'Ja jeder, der Geschwister, Eltern, Weib und Kind oder Äcker und Häuser um meines Namens willen fahren läßt, der soll reichen Ersatz dafür empfangen und das ewige Leben als Erbe bekommen.',
        30: 'Doch in vielen Fällen werden die Ersten die Letzten und die Letzten die Ersten sein.',
    },
    20: {
        1: 'Denn das Königreich der Himmel gleicht einem Hausherrn, der frühmorgens ausging, um Arbeiter für seinen Weinberg zu mieten.',
        2: 'Er vereinbarte mit ihnen einen Silberling als Tagelohn und sandte sie in seinen Weinberg.',
        3: 'Um die dritte Stunde ging er wieder aus und sah andere auf dem Marktplatz unbeschäftigt stehen;',
        4: "zu denen sprach er: 'Geht auch ihr in meinen Weinberg! Ich will euch geben, was recht ist.'",
        5: 'Sie gingen hin. Wiederum ging er aus um die sechste und um die neunte Stunde und tat ebenso.',
        6: "Als er aber um die elfte Stunde nochmals ausging, fand er andere dastehen und sprach zu ihnen: 'Warum steht ihr hier den ganzen Tag unbeschäftigt?'",
        7: "Sie antworteten ihm: 'Es hat uns niemand in Arbeit genommen.' Er sprach zu ihnen: 'Geht auch ihr in meinen Weinberg!'",
        8: "Am Abend aber sprach der Herr des Weinbergs zu seinem Verwalter: 'Rufe die Arbeiter und zahle ihnen den Lohn: fang bei den letzten an und höre bei den ersten auf!'",
        9: 'Da kamen die Arbeiter der elften Stunde, und jeder empfing einen Silberling.',
        10: 'Als nun die ersten kamen, meinten sie, sie würden mehr empfangen; doch auch sie bekamen jeder einen Silberling.',
        11: 'Als sie den empfingen, murrten sie gegen den Hausherrn',
        12: "und sagten: 'Diese letzten haben nur eine Stunde gearbeitet, und du hast sie uns gleichgestellt, die wir des ganzen Tages Last und Hitze ertragen haben.'",
        13: "Er aber antwortete einem von ihnen: 'Mein Freund, ich tue dir nicht unrecht. Hast du nicht einen Silberling mit mir vereinbart?",
        14: 'Nimm dein Geld und geh! Ich will aber diesen letzten ebensoviel geben wie dir.',
        15: "Darf ich etwa nicht mit meinem Geld machen, was ich will? Oder bist du neidisch, weil ich so gütig bin?'",
        16: 'So werden die Letzten die Ersten und die Ersten die Letzten sein."',
        17: 'Jesus zog dann weiter nach Jerusalem und hatte nur die Zwölf als besondere Begleiter bei sich. Während der Wanderung sprach er zu ihnen:',
        18: '"Jetzt gehen wir nach Jerusalem. Dort wird der Menschensohn den Hohenpriestern und den Schriftgelehrten überliefert werden.',
        19: 'Die werden ihn zum Tod verurteilen und ihn dann den Heiden überantworten, daß er verspottet, gegeißelt und gekreuzigt werde. Aber am dritten Tag wird er wieder auferstehen."',
        20: 'Da trat die Frau des Zebedäus mit ihren Söhnen zu ihm und trug ihm fußfällig eine Bitte vor.',
        21: 'Er fragte sie: "Was wünschst du?" Sie sprach zu ihm: "Bestimme, daß meine beiden Söhne hier dereinst in deinem Königreich dir zur Rechten und zur Linken sitzen!"',
        22: 'Jesus erwiderte: "Ihr versteht nicht, um was ihr bittet. Könnt ihr den Kelch trinken, den ich trinken soll?" Sie antworteten ihm: "Ja, das können wir."',
        23: 'Da sprach er zu ihnen: "Meinen Kelch sollt ihr freilich trinken. Aber die Sitze zu meiner Rechten und zu meiner Linken kann ich euch nicht verleihen; die werden nur denen zuteil, für die sie mein Vater bestimmt hat."',
        24: 'Als die anderen Zehn dies hörten, äußerten sie ihren Unwillen über die beiden Brüder.',
        25: 'Da rief sie Jesus zu sich und sprach: "Ihr wißt, daß die Herrscher über die Völker unumschränkt gebieten, und daß die Großen ihre Untergebenen ihre Macht fühlen lassen.',
        26: "So soll's bei euch nicht sein. Im Gegenteil: wer unter euch der groß sein will, der sei euer Diener;",
        27: 'und wer unter euch der Erste sein will, der sei euer Knecht.',
        28: 'So ist ja auch der Menschensohn nicht gekommen, um sich dienen zu lassen, sondern um selbst zu dienen und sein Leben dahinzugeben als Lösegeld für viele."',
        29: 'Als sie Jericho verließen, folgte ihm viel Volk.',
        30: 'Und sieh, es saßen zwei Blinde am Weg. Als sie hörten, Jesus käme vorbei, da riefen sie: "Herr, erbarme dich unser, du Davidssohn!"',
        31: 'Die Leute aber fuhren sie mit rauhen Worten an, sie sollten schweigen. doch sie riefen nur noch lauter: "Herr, erbarme dich unser, du Davidssohn!"',
        32: 'Da blieb Jesus stehen, rief sie zu sich und fragte sie: "Was begehrt ihr von mir?"',
        33: 'Sie antworteten ihm: "Herr, laß sich unsere Augen öffnen!"',
        34: 'Da rührte Jesus voll Mitleid ihre Augen an, und sofort wurden sie wieder sehend und folgten ihm.',
    },
    21: {
        1: 'Als sie in die Nähe von Jerusalem kamen, nach Bethphage, an den Ölberg, entsandte Jesus zwei Jünger',
        2: 'mit dem Auftrag: "Geht in das Dorf, das vor euch liegt! Dort werdet ihr gleich am Eingang eine Eselin angebunden finden und bei ihr ein Füllen. Bindet beide Tiere los und bringt sie her zu mir!',
        3: 'Und will euch jemand dreinreden, so spracht: \'Der Herr bedarf ihrer\' — dann wird er sie ohne weiteres ziehenlassen."',
        4: 'Dies ist geschehen, damit sich der Ausspruch des Propheten erfülle:',
        5: 'Sagt der Tochter Zion: Sieh, dein König kommt zu dir, voll Demut und auf einem Esel reitend, und zwar auf einem Lasttierfüllen.',
        6: 'Die Jünger gingen hin und taten, wie ihnen Jesus geboten hatte:',
        7: 'sie brachten die Eselin und das Füllen, legten ihre Mäntel auf der Tiere Rücken, und er setzte sich darauf.',
        8: 'Sehr viele Leute aber breiteten ihre Mäntel auf den Weg, andere hieben Zweige von den Bäumen und streuten sie auf die Straße.',
        9: 'Und alle, die mit ihm gingen — vorn im Zug und hinterdrein —, die riefen laut: Heil dem Sohn Davids! Gesegnet sei, der da kommt im Namen des Herrn! Heil soll erschallen droben in der Höhe!"',
        10: 'Bei seinem Einzug in Jerusalem geriet die ganze Stadt in Aufregung; man fragte: "Wer ist das?"',
        11: 'Die Leute antworteten: "Das ist der Prophet Jesus aus Nazaret in Galiläa."',
        12: 'Dann ging Jesus in den Tempel Gottes: er trieb alle hinaus, die im Tempel verkauften und kauften; er stieß die Tische der Wechsler und die Bänke der Taubenhändler um',
        13: 'und sprach zu ihnen: "Es steht geschrieben: Mein Haus soll ein Bethaus heißen; ihr aber habt eine Räuberhöhle daraus gemacht."',
        14: 'Dort im Tempel kamen Blinde und Lahme zu ihm, und er heilte sie.',
        15: 'Als aber die Hohenpriester und Schriftgelehrten die Wunder sahen, die er tat, und hörten, wie die Kinder im Tempel riefen: "Heil dem Sohn Davids!", da wurden sie unwillig',
        16: 'und sprachen zu ihm: "Hörst du nicht, was die hier rufen?" Jesus antwortete ihnen: "Jawohl! Habt ihr denn nie das Wort gelesen: Aus Kinder- und Säuglingsmund hast du dir Lob bereitet?"',
        17: 'Damit ließ er sie stehen und ging aus der Stadt hinaus nach Bethanien, wo er übernachtete.',
        18: 'Frühmorgens bei der Rückkehr in die Stadt empfand er Hunger.',
        19: 'Da sah er einen einzeln stehenden Feigenbaum am Wege. Auf den ging er zu, aber er fand nur Blätter daran. Da sprach er zu dem Baum: "In Zukunft sollst du niemals wieder Frucht tragen!" Sofort verdorrte der Feigenbaum.',
        20: 'Bei diesem Anblick waren die Jünger verwundert und fragten: "Wie hat der Feigenbaum sofort verdorren können?"',
        21: 'Jesus antwortete ihnen: "Wahrlich, ich sage euch: Wenn ihr Glauben hättet und nicht zweifeltet, so könntet ihr nicht nur dasselbe tun, was an dem Feigenbaum geschehen ist; sondern wenn ihr zu dem Berge dort sagtet: \'Heb dich von deiner Stelle und stürze dich ins Meer\', so würde es geschehen.',
        22: 'Ja alles, was ihr im Glauben im Gebet erfleht, das werdet ihr empfangen."',
        23: 'Als er wieder im Tempel war und dort lehrte, traten die Hohenpriester und die Ältesten des Volkes zu ihm mit der Frage: "Mit welchem Recht tust du dies, und wer hat dir das Recht dazu gegeben?"',
        24: 'Jesus erwiderte ihnen: "Ich will euch auch eine Frage vorlegen; gebt ihr mir darauf Antwort, so will ich euch auch sagen, mit welchem Recht ich dies tue:',
        25: 'Woher stammte die Taufe des Johannes? Vom Himmel oder von Menschen?" Sie überlegten miteinander: "Sagen wir: \'vom Himmel\', so wird er uns fragen: \'Warum habt ihr ihm denn nicht geglaubt?\'',
        26: 'Antworten wir aber: \'von Menschen\', so haben wir das Volk zu fürchten, denn das sieht allgemein Johannes als Propheten an."',
        27: 'Da erwiderten sie Jesus: "Wir wissen es nicht." Darauf sprach er zu ihnen: "So sage ich euch auch nicht, mit welchem Recht ich dies tue."',
        28: '"Was meint ihr nun? Ein Mann hatte zwei Söhne. Er ging zu dem ersten und sagte: \'Mein Sohn, geh und arbeite heute in meinem Weinberg!\'',
        29: "Der erwiderte: 'Jawohl, Herr!' aber er ging nicht hin.",
        30: "Dann wandte sich der Vater mit denselben Worten an den zweiten Sohn. Der entgegnete: 'Ich habe keine Lust.' Nachher aber tat's ihm leid, und er ging und er ging doch.",
        31: 'Wer von den beiden hat nun seines Vaters Willen ausgeführt?" Sie sprachen: "Der zweite." Da fuhr Jesus fort: "Wahrlich, ich sage euch: Die Zöllner und die Dirnen kommen eher in Gottes Königreich als ihr.',
        32: 'Denn Johannes ist zu euch gekommen, um euch den rechten Weg zu zeigen; aber ihr habt ihm nicht geglaubt. Die Zöllner dagegen und die Dirnen haben ihm geglaubt. Ihr habt das zwar gesehen, doch anderes Sinnes seid ihr trotzdem nachher nicht geworden: ihr habt ihm nicht geglaubt.',
        33: 'Hört noch ein anderes Gleichnis: Ein Hausherr pflanzte einen Weinberg; er zog einen Zaun darum, grub eine Kelterkufe darin aus und baute einen Turm. Dann verpachtete er ihn an Winzer und ging außer Landes.',
        34: 'Als sich nun die Zeit der Weinlese nahte, sandte er seine Knechte zu den Winzern, damit sie den Teil der Früchte abholten, der ihm zukam.',
        35: 'Die Winzer aber ergriffen diese Knechte: den einen mißhandelten sie, den anderen erschlugen sie, den dritten steinigten sie.',
        36: 'Dann sandte er andere Knechte, mehr als zuerst; doch mit diesen verfuhren sie ebenso..',
        37: 'Zuletzt sandte er seinen Sohn zu ihnen, denn er dachte: vor meinem Sohn werden sie doch Ehrfurcht haben.',
        38: "Als aber die Winzer den Sohn sahen, sprachen sie untereinander: 'Ha, da kommt der Erbe! Auf! laßt uns ihn töten und sein Erbgut in Besitz nehmen!'",
        39: 'Und sie ergriffen ihn, stießen ihn aus dem Weinberg und töteten ihn.',
        40: 'Wenn nun der Weinbergsbesitzer kommt, was wird er diesen Winzern tun?"',
        41: 'Sie erwiderten ihm: "Er wird diese Übeltäter übel umbringen und seinen Weinberg anderen Winzern verpachten, die ihm die Früchte zur rechten Zeit abliefern."',
        42: 'Jesus sprach zu ihnen: "(Allerdings!) Habt ihr denn niemals in der Schrift das Wort gelesen: Der Stein, den die Bauleute verworfen haben, der ist zum Eckstein geworden. Dies ist eine Tat des Herrn, und sie ist wunderbar in unseren Augen?',
        43: 'Darum sage ich euch: Gottes Königreich soll euch genommen und einem Volk gegeben werden, das auch die Früchte trägt, die diesem Reich Ehre machen."',
        45: 'Als die Hohenpriester und die Pharisäer seine Gleichnisse hörten, merkten sie, daß er von ihnen redete.',
        46: 'Da sannen sie darauf, ihn festzunehmen; aber sie fürchteten sich vor dem Volk, denn das hielt ihn für einen Propheten.',
    },
    22: {
        1: 'Jesus nahm von neuem das Wort zu Gleichnisreden und sprach zu ihnen:',
        2: '"Das Himmelreich gleicht einem König, der seinem Sohn die Hochzeit ausrichtete.',
        3: 'Er sandte seine Knechte aus, um die schon geladenen Gäste zur Hochzeit zu entbieten; aber sie hatten keine Lust zu kommen',
        4: "Da sandte er nochmals andere Knechte mit dem Auftrag: 'Sagt den geladenen Gästen: Mein Frühmahl ist nun fertig, meine Ochsen und mein Mastvieh ist geschlachtet. Alles ist bereit, kommt zur Hochzeit!'",
        5: 'Doch, ohne diese Botschaft zu beachten, gingen die einen von den Gästen auf dem Acker oder beim Handel ihren täglichen Geschäften nach.',
        6: 'Die anderen aber ergriffen des Königs Knechte, verhöhnten sie, ja brachten sie ums Leben.',
        7: 'Da ward der König zornig: er sandte seine Heere aus; die brachten diese Mörder um und verbrannten ihre Stadt.',
        8: "Dann sprach er zu seinen Knechten: 'Das Hochzeitsmahl ist fertig; doch die geladenen Gäste waren nicht wert, daran teilzunehmen.",
        9: "So geht denn vor die Stadt hinaus: dorthin, wo die Feldwege beginnen, und alle, die ihr findet, ladet zur Hochzeit!'",
        10: 'Die Knechte gingen aus auf die Landstraßen, und alle die sie fanden, führten sie herbei: Böse sowohl wie Gute. Und der Hochzeitssaal füllte sich mit Gästen.',
        11: 'Nun trat der König ein, um sich die Gäste anzusehen. Da nahm er eine wahr, der trug kein Hochzeitskleid.',
        12: "Und er sprach zu ihm: 'Mein Freund, wie hast du Einlaß finden können ohne Hochzeitskleid?' Er aber schwieg.",
        13: "Da sprach der König zu den Dienern: 'Bindet ihn an Händen und Füßen und werft ihn in die Finsternis hinaus!' Dort wird lautes Klagen und Zähneknirschen sein.",
        14: 'Denn viele sind berufen, aber nur wenige sind auserwählt."',
        15: 'Da gingen die Pharisäer hin und berieten sich, wie sie ihn in seinen eigenen Worten fangen könnten.',
        16: 'Sie sandten deshalb ihre Schüler zu ihm, die von Anhängern des Herodes begleitet waren. Die sprachen zu ihm: "Meister, wir wissen, du bist aufrichtig und lehrst in aller Wahrheit Gottes Weg; dabei nimmst du auf niemand Rücksicht, denn Menschengunst gilt nicht bei dir.',
        17: 'So sag uns denn, was meinst du: Darf man dem Kaiser Steuer zahlen oder nicht?"',
        18: 'Jesus aber merkte ihre böse Absicht und sprach zu ihnen: "Was versucht ihr mich, ihr Heuchler?',
        19: 'Zeigt mir die Steuermünze!" Da reichten sie ihm einen Silberling.',
        20: 'Und er fragte sie: "Wessen Bild und Inschrift steht hier?"',
        21: 'Sie antworteten ihm: "Des Kaisers." Da sprach er zu ihnen: "So gebt dem Kaiser, was dem Kaiser gebührt, und Gott, was Gott gebührt!"',
        22: 'Über diese Antwort waren sie verwundert, und sie verließen ihn und gingen ihres Weges.',
        23: 'An demselben Tag traten Sadduzäer zu ihm, die da behaupteten, es gebe keine Auferstehung, und legten ihm auch eine Frage vor.',
        24: '"Meister", so sprachen sie, "Mose hat gesagt: Stirbt jemand kinderlos, so soll sein Bruder die verwitwete Schwägerin zum Weib nehmen und (mit ihr) seinem (verstorbenen) Bruder Nachkommen erwecken.',
        25: 'Nun lebten unter uns sieben Brüder. Der erste freite und starb kinderlos: so hinterließ er seine Witwe seinem Bruder.',
        26: 'Ebenso ging es mit dem zweiten und dritten, ja mit allen sieben.',
        27: 'Zuletzt von allen starb auch die Frau.',
        28: 'Wem von diesen sieben wird sie nun bei der Auferstehung als Gattin angehören? Sie haben sie ja alle zur Frau gehabt."',
        29: 'Jesus antwortete ihnen: "Ihr seid im Irrtum, denn ihr kennt die Schriften nicht noch Gottes Macht.',
        30: 'Die Auferstandenen freien nicht und lassen sich nicht freien, sondern sind wie Gottes Engel im Himmel.',
        31: 'Was aber die Auferstehung der Toten betrifft, habt ihr da nicht gelesen, was Gott zu euch in dem bekannten Wort spricht:',
        32: 'Ich bin der Gott Abrahams, der Gott Isaaks und der Gott Jakobs? Gott ist nun aber nicht ein Gott der Toten, sondern der Lebendigen."',
        33: 'Das Volk, das diese Worte hörte, staunte über seine Lehre.',
        34: 'Als die Pharisäer erfuhren, er habe die Sadduzäer zum Schweigen gebracht, versammelten sie sich.',
        35: 'Einer aus ihrer Mitte, ein Gesetzeslehrer, wollte ihm eine Falle stellen und fragte ihn deshalb:',
        36: '"Meister, welches ist das wichtigste Gebot im Gesetz?"',
        37: 'Er antwortete ihm: "Du sollst den Herrn, deinen Gott, lieben mit ganzem Herzen, mit ganzer Seele und mit allem Denken.',
        38: 'Dies ist das wichtigste und höchste Gebot.',
        39: 'Das andere aber, das ihm gleichsteht, lautet: Du sollst deinen Nächsten lieben wie dich selbst.',
        40: 'In diesen beiden Geboten hängen das ganze Gesetz und die Propheten."',
        41: 'Als dann die Pharisäer beisammen waren, fragte sie Jesus:',
        42: '"Was denkt ihr über den Messias? Wessen Sohn ist er?" Sie antworteten ihm: "Davids."',
        43: 'Da sprach Jesus zu ihnen: "Wie kann ihn denn David, vom Geist erleuchtet, Herr nennen, in dem Ausspruch:',
        44: 'Der Herr hat gesagt zu meinem Herrn: Sitze du zu meiner Rechten, bis ich dir deine Feinde zu Füßen lege.?',
        45: 'Wenn ihn nun David seinen Herrn nennt, wie kann er da zugleich sein Sohn sein?"',
        46: 'Darauf konnte ihm niemand ein Wort erwidern, und seitdem wagte auch keiner mehr, ihm eine Frage vorzulegen.',
    },
    23: {
        1: 'Dann wandte sich Jesus an das Volk und an seine Jünger.',
        2: '"Moses Lehrstuhl", so begann er, "haben jetzt die Schriftgelehrten und die Pharisäer besetzt.',
        3: 'Alles nun, was sie euch sagen, das tut und haltet! Nach ihren Werken aber sollt ihr euch nicht richten. Denn sie lehren anders, als sie tun.',
        4: 'Sie binden Bündel schwerer Lasten zusammen und legen sie den Leuten auf die Schulter; sie selbst aber haben keine Lust, diese Lasten auch nur mit einer Fingerspitze zu berühren.',
        5: 'Bei all ihrem Tun wollen sie die öffentliche Aufmerksamkeit erregen: Sie tragen breite Gebetsriemen und lange Mantelquasten.',
        6: 'Beim Mahl sitzen sie gern obenan, und in der gottesdienstlichen Versammlung wollen sie die Ehrenplätze haben;',
        7: "auf den Straßen soll man sie voll Ehrfurcht grüßen, und sie lassen sich den Namen 'Meister' geben.",
        8: 'Ihr aber sollt euch nicht so nennen lassen; denn Einer ist euer Meister, und ihr seid alle Brüder.',
        9: "Ihr sollt auch niemand auf Erden euern 'Vater' nennen; denn Einer ist euer Vater: der Vater im Himmel.",
        10: "Auch sollt ihr euch nicht 'Lehrer' nennen lassen; denn Einer ist euer Lehrer: der Messias.",
        11: 'Der Größte unter euch soll allen anderen dienen.',
        12: 'Wer sich selbst erhöht, der soll erniedrigt werden; und wer sich selbst erniedrigt, der soll erhöht werden.',
        13: 'Weh euch, ihr Schriftgelehrten und Pharisäer, ihr Heuchler! Ihr schließt die Tür des Himmelreiches vor den Leuten zu. Ihr selbst geht nicht hinein und laßt auch die nicht ein, die es gern wollen.',
        15: 'Weh euch, ihr Schriftgelehrten und Pharisäer, ihr Heuchler! Ihr zieht über Land und Meer, um einen einzigen Jünger zu gewinnen. Und ist euch das gelungen, so macht ihr ihn zu einem Kind der Hölle, das zweimal ärger ist als ihr!',
        16: 'Weh euch, ihr blinden Führer! Ihr sagt: Wer bei dem Tempel schwört, des Eid gilt nichts. Wer aber bei dem Gold des Tempels schwört, der ist gebunden.',
        17: 'Ihr Toren und ihr Blinden! Was steht denn höher: das Gold oder der Tempel, der doch dem Gold erst die Weihe gibt?',
        18: 'Wer bei dem Altar schwört — so sagt ihr ferner —, des Eid gilt nichts. Wer aber bei der Opfergabe auf dem Altar schwört, der ist gebunden.',
        19: 'Ihr Blinden! Was steht denn höher: die Opfergabe oder der Altar, der doch der Opfergabe erst die Weihe gibt?',
        20: 'Wer also bei dem Altar schwört, der schwört bei ihm und allem, was darauf ist.',
        21: 'Und wer beim Tempel schwört, der schwört bei ihm und dem, der darinnen wohnt.',
        22: 'Und wer beim Himmel schwört, der schwört bei Gottes Thron und dem, der darauf sitzt.',
        23: 'Weh euch, ihr Schriftgelehrten und Pharisäer, ihr Heuchler! Von Minze, Dill und Kümmel gebt ihr Zehnten, was aber im Gesetz viel höher steht: Gerechtigkeit, Barmherzigkeit und Treue — das laßt ihr außer acht. Dies solltet ihr vor allem üben, doch jenes auch nicht unterlassen.',
        24: 'Ihr blinden Führer, die Mücke schafft ihr weg, und das Kamel verschluckt ihr!',
        25: 'Weh euch, ihr Schriftgelehrten und Pharisäer, ihr Heuchler! Die Becher und die Schüsseln haltet ihr von außen rein, inwendig aber sind sie voller Raub und Gier!',
        26: 'Du blinder Pharisäer, erst reinige den Becher drinnen, dann ist sein Äußeres schon von selber rein!',
        27: 'Weh euch, ihr Schriftgelehrten und Pharisäer, ihr Heuchler! Ihr gleicht getünchten Gräbern',
        28: 'So seht auch ihr von außen gerecht und ehrbar aus, inwendig aber seid ihr voller Heuchelei und Frevel.',
        29: 'Weh euch, ihr Schriftgelehrten und Pharisäer, ihr Heuchler! Ihr pflegt die Gräber der Propheten und schmückt die Grabdenkmäler der Gerechten,',
        30: "und dabei rühmt ihr euch: 'Wenn wir unserer Väter Zeit gelebt, wir hätten nicht mit ihnen der Propheten Blut vergossen.'",
        31: 'Damit bezeugt ihr aber selbst, daß ihr die Söhne der Prophetenmörder seid!',
        32: 'So macht denn ihr das Maß der Sünden eurer Väter voll!',
        33: 'Ihr Schlangen und ihr Natternbrut, wie wollt ihr nur der Hölle Strafgericht entrinnen?',
        34: 'Darum seht: ich sende euch Propheten, Weise, Schriftgelehrte. Die einen werdet ihr in euern Versammlungshäusern geißeln und sie verfolgen von einer Stadt zur anderen.',
        35: 'So wird sich an euch rächen all das unschuldige Blut, das da vergossen ist auf Erden: Vom Blut des gerechten Abel an bis auf Sacharjas Blut, des Sohnes Berechjas, den ihr gemordet zwischen Tempel und Altar.',
        36: 'Wahrlich, ich sage euch: Die Strafe für das alles wird kommen über dies Geschlecht!',
        37: 'Jerusalem, Jerusalem, du tötest die Propheten und steinigst Gottes Boten! Wie oft habe ich deine Kinder um mich sammeln wollen, wie eine Henne ihre Küchlein unter ihre Flügel sammelt! Doch ihr habt nicht gewollt!',
        38: 'Darum soll euch euer Haus verödet liegen!',
        39: 'Denn ich sage euch: Ihr sollt mich ferner nicht mehr sehen, bis ihr einst ruft: \'Gesegnet sei, der da kommt im Namen des Herrn!\'"',
    },
    24: {
        1: 'Darauf verließ Jesus den Tempelplatz. Als er so mit seinen Jüngern dahinging, traten diese zu ihm und machten ihn auf den prächtigen Bau des Tempels aufmerksam.',
        2: 'Er aber sprach zu ihnen: "Seht ihr nicht dies alles? Wahrlich, ich sage euch: Kein Stein wird hier auf dem anderen bleiben; alles soll zerstört werden."',
        3: 'Er ging dann auf den Ölberg und setzte sich dort nieder. Da traten die Jünger, als sie allein waren, zu ihm und sprachen: "Sag uns doch: Wann wird dies geschehen, und was ist das Zeichen deiner Wiederkunft und des Endes dieser Weltzeit?"',
        4: 'Jesus antwortete ihnen: "Habt acht, daß euch niemand verführe!',
        5: "Denn mancher wird kommen unter meinem Namen und behaupten: 'Ich bin der Messias!' Diese Leute werden viele irreführen.",
        6: 'Ihr werdet auch hören von Kriegen und Kriegsgerüchten. Laßt euch dadurch nicht schrecken! Denn das alles muß so kommen. doch es ist noch nicht das Ende.',
        7: 'Denn ein Volk wird sich erheben gegen das andere und ein Reich gegen das andere; hier und da werden Hungersnöte und Erdbeben sein.',
        8: 'Dies alles ist aber erst der Anfang der Nöte.',
        9: 'Zu der Zeit wird man euch verfolgen und töten; ja alle Völker werden euch hassen, weil ihr meine Jünger seid.',
        10: 'Dann werden viele vom Glauben abfallen, sie werden einander verraten und hassen.',
        11: 'Auch werden falsche Propheten in großer Zahl auftreten und viele verführen.',
        12: 'Und weil die Gesetzlosigkeit überhandnimmt, wird die Liebe bei den meisten erkalten.',
        13: 'Wer aber bis ans Ende ausharrt, der soll errettet werden.',
        14: 'Die Frohe Botschaft vom Königreich, die schon jetzt erschallt, soll in der ganzen Welt verkündigt werden, damit alle Völker ein Zeugnis empfangen. Dann erst wird das Ende kommen.',
        15: 'Seht ihr nun den Greuel der Verwüstung an heiliger Stätte stehen, wovon Daniel, der Prophet, geredet hat — wer das liest, beachte es wohl! —,',
        16: 'dann sollen, die in Judäa sind, in die Berge fliehen.',
        17: 'Wer auf dem Dach ist, gehe nicht erst ins Haus hinunter, um noch seine Habe zu holen;',
        18: 'und wer auf dem Feld ist, der kehre nicht in die Wohnung zurück, um sich noch sein Oberkleid zu holen.',
        19: 'Doch weh den Frauen, die Kinder erwarten, und stillenden Müttern in jenen Tagen!',
        20: 'Betet aber, daß eure Flucht nicht in den Winter oder auf den Sabbat falle!',
        21: 'Denn es wird dann eine große Trübsal sein, wie noch keine gewesen ist von Anfang der Welt bis heute, und wie auch keine wieder kommen wird.',
        22: 'Und wären diese Tage nicht abgekürzt, so würde kein Mensch errettet. Doch um der Auserwählten willen werden jene Tage abgekürzt.',
        23: "Wenn euch dann jemand sagt: 'Jetzt ist der Messias hier oder da', so glaubt es nicht!",
        24: 'Denn es werden falsche Messiasse und falsche Propheten auftreten und große Zeichen und Wunder tun, um womöglich auch die Auserwählten zu verführen.',
        25: 'Ich warne euch!',
        26: "Sagt man euch also: 'Er ist jetzt in der Wüste', so geht nicht hinaus, oder: 'er ist in diesem oder jenem Haus', so glaubt es nicht!",
        27: 'Denn wie der Blitz im Osten aufzuckt, und bis zum Westen leuchtet, so wird auch die Wiederkunft des Menschensohnes sein.',
        28: 'Denn wo der Leichnam liegt, da sammeln sich die Geier.',
        29: 'Gleich aber nach jener Trübsalszeit wird sich die Sonne verfinstern und der Mond kein Licht mehr geben, die Sterne werden vom Himmel fallen, und die Himmelskräfte werden wanken.',
        30: 'Dann erscheint am Himmel das Zeichen des Menschensohnes, und bei seinem Anblick werden wehklagen alle Völker der Erde; denn sie werden den Menschensohn kommen sehen auf des Himmels Wolken mit großer Macht und Herrlichkeit.',
        31: 'Und er wird seine Boten senden; die sollen die Posaune blasen, daß es weithin schallt: so werden sie seine Auserwählten zu ihm sammeln von allen Himmelsgegenden aus aller Welt.',
        32: 'Vom Feigenbaum entnehmt eine Lehre: Wenn seine Zweige saftig werden und Blätter treiben, so wißt ihr, daß der Sommer nahe ist.',
        33: 'So sollt ihr auch, wenn ihr dies alles seht, gewiß sein, daß Er nahe vor der Tür ist.',
        34: 'Wahrlich, ich sage euch: Diese Weltzeit ist nicht eher zu Ende, als bis dies alles geschehen ist.',
        35: 'Himmel und Erde werden vergehen, meine Worte aber werden nimmermehr vergehen.',
        36: 'Den Tag und die Stunde aber kennt niemand, auch die Engel des Himmels nicht, sondern nur mein Vater allein.',
        37: "Wie es aber zuging in Noahs Tagen, so wird's auch zugehen bei der Wiederkunft des Menschensohnes.",
        38: "In den Tagen vor der Sintflut aßen und tranken die Menschen, sie nahmen zur Ehe und gaben zur Ehe. So trieben sie's bis zu dem Tage, als Noah in die Arche ging;",
        39: "und sie ahnten die Gefahr nicht, bis die Flut hereinbrach und sie alle hinwegraffte. Ganz ebenso wird's bei der Wiederkunft des Menschensohnes sein.",
        40: 'Da werden zwei Männer auf demselben Acker arbeiten: der eine wird mitgenommen, der andere bleibt zurück.',
        41: 'Zwei Frauen werden an derselben Mühle mahlen: die eine wird mitgenommen, die andere bleibt zurück.',
        42: 'So wacht nun! Ihr wißt ja nicht, an welchem Tag euer Herr kommt.',
        43: 'Das seht ihr ein: wenn ein Hausherr wüßte, zu welcher Nachtstunde der Dieb käme, so bliebe er wach und ließe nicht in sein Haus einbrechen.',
        44: 'Darum haltet auch ihr euch immerfort bereit; denn der Menschensohn kommt zu einer Stunde, da ihr es nicht vermutet.',
        45: 'Wäre doch jeder Knecht treu und klug, den ein Hausherr über sein Gesinde setzt, damit er ihnen Speise gebe zu rechter Zeit!',
        46: 'Wohl dem Knecht, den sein Herr bei seiner Rückkehr also tätig findet!',
        47: 'Wahrlich, ich sage euch: Er wird ihn über alle seine Güter setzen.',
        48: "Ist aber der Knecht gewissenlos und denkt in seinem Herzen: 'Mein Herr bleibt noch lange weg';",
        49: 'fängt er dann an, die ihm untergebenen Knechte zu mißhandeln, während er mit Trunkenbolden schmaust und zecht;',
        50: "so wird sein Herr ihn überraschen an einem Tag, wo er's nicht erwartet.",
        51: 'Dann wird er ihn blutig peitschen lassen und ihn an den Ort verweisen, wo die Heuchler sind. Dort wird lautes Klagen und Zähneknirschen sein.',
    },
    25: {
        1: 'Dann gleicht das Königreich der Himmel zehn Jungfrauen, die mit ihren Lampen in der Hand dem Bräutigam entgegengingen.',
        2: 'Aber fünf von ihnen waren töricht, und nur fünf waren klug.',
        3: 'Die törichten nahmen wohl ihre Lampen mit, aber keinen Ölvorrat.',
        4: 'Die klugen aber hatten außer ihren Lampen auch noch in Krügen Öl bei sich.',
        5: 'Als sich nun die Ankunft des Bräutigams verzögerte, nickten sie alle ein und fielen in Schlaf.',
        6: "Um Mitternacht aber ertönte der laute Ruf: 'Jetzt kommt der Bräutigam! Geht und holt ihn festlich ein!'",
        7: 'Da wurden alle Jungfrauen wach und setzten ihre Lampen instand.',
        8: "Nun sprachen die törichten zu den klugen: 'Gebt uns von euerm Öl, denn unsere Lampen verlöschen.'",
        9: "Die klugen erwiderten: 'O nein! Es reicht nicht aus für uns und euch; geht lieber zu den Krämern und kauft euch Vorrat.'",
        10: 'Als sie auf dem Weg waren, um sich Öl zu kaufen, kam der Bräutigam. Die Jungfrauen, die bereit waren, gingen mit ihm in den Hochzeitssaal, und die Tür ward verschlossen.',
        11: "Später kamen auch die anderen Jungfrauen und riefen: 'Herr, Herr, tue uns auf!'",
        12: "Er aber antwortete: 'Wahrlich, ich sage euch: Ich kenne euch nicht!'",
        13: 'Seid darum recht wachsam; denn Tag und Stunde sind euch unbekannt!',
        14: 'Es ist (mit dem Königreich der Himmel) wie mit einem Mann, der ins Ausland reisen wollte: der ließ vorher seine Knechte rufen und übergab ihnen sein Vermögen.',
        15: 'Dem einen gab er fünf Talente, dem anderen zwei, dem dritten eins, jedem nach seiner Fähigkeit. Dann reiste er ab.',
        16: 'Sofort machte sich der Empfänger der fünf Talente daran, das Geld vorteilhaft anzulegen, und gewann fünf andere dazu.',
        17: 'Ebenso gewann der Empfänger der zwei Talente noch zwei andere.',
        18: 'Der aber nur ein Talent empfangen hatte, ging hin, machte eine Grube in die Erde und verbarg darin das Geld seines Herrn.',
        19: 'Nach langer Zeit kam der Herr dieser Knechte zurück und rechnete mit ihnen ab.',
        20: "Da erschien der Empfänger der fünf Talente, brachte noch fünf andere mit und sprach: 'Herr, fünf Talente hast du mir gegeben; sieh, fünf andere habe ich damit gewonnen.'",
        21: "Da sprach sein Herr zu ihm: 'Recht so, du wackerer und treuer Knecht! Du bist über wenigem treu gewesen, ich will dich über viel setzen. Nimm teil an deines Herrn Freudenfest!'",
        22: "Dann erschien der Empfänger der zwei Talente und sprach: 'Herr, zwei Talente hast du mir gegeben; sieh, zwei andere habe ich damit gewonnen.'",
        23: "Da sprach sein Herr zu ihm: 'Recht so, du wackerer und treuer Knecht! Du bist über wenig treu gewesen, ich will dich über viel setzen. Nimm teil an deines Herrn Freudenfest!'",
        24: "Endlich erschien der Empfänger des einen Talents und sprach: 'Herr, ich kenne dich als einen harten Mann: du willst ernten, wo du nicht gesät, und Korn einsammeln von der Tenne, wo du nicht geworfelt hast.",
        25: "Deshalb bin ich aus Furcht hingegangen und habe dein Talent in der Erde verborgen. Hier hast du dein Geld wieder.'",
        26: "Da antwortete ihm sein Herr: 'Du gewissenloser, fauler Knecht! Du weißt, ich will da ernten, wo ich nicht gesät, und Korn einsammeln von der Tenne, wo ich nicht geworfelt habe?",
        27: 'Nun, dann hättest du mein Geld wenigstens bei der Bank anlegen sollen: so hätte ich doch bei meiner Rückkehr mein Eigentum mit Zins zurückbekommen.',
        28: 'Nehmt ihm nun das Talent und gebt es dem, der die zehn Talente hat. —',
        29: 'Denn wer (viel) hat, der soll noch mehr empfangen, daß er die Fülle haben; doch wer nur wenig hat, dem soll sogar das wenige genommen werden. —',
        30: "Den unbrauchbaren Knecht aber werft in die Finsternis hinaus: dort wird lautes Klagen und Zähneknirschen sein.'",
        31: 'Ist aber der Menschensohn in seiner Herrlichkeit gekommen, und alle Engel mit ihm, dann setzt er sich auf seinen herrlichen Königsthron.',
        32: 'Alle Völker versammeln sich vor seinem Angesicht. Und er wird sie voneinander scheiden, wie ein Hirte die Schafe von den Ziegenböcken scheidet,',
        33: 'und er stellt die Schafe zu seiner Rechten, die Böcke aber zur Linken.',
        34: "Dann wird der König sagen zu denen, die ihm zur Rechten stehen: 'Kommt her, ihr Gesegneten meines Vaters, nehmt in Besitz das Königreich, das euch bereitet ist seit Grundlegung der Welt!",
        35: 'Denn ich bin hungrig gewesen, und ihr habt mir Speise gereicht; ich bin durstig gewesen, und ihr habt mich getränkt; ich bin obdachlos gewesen, und ihr habt mich aufgenommen;',
        36: "ich bin nackt gewesen, und ihr habt mich besucht; ich bin im Gefängnis gewesen, und ihr seid zu mir gekommen.'",
        37: "Dann werden ihm die Gerechten erwidern: 'Herr, wann haben wir dich hungrig gesehen und gespeist, oder durstig und dich getränkt?",
        38: 'Wann haben wir dich obdachlos gesehen und in unser Haus genommen, oder nackt und dich bekleidet?',
        39: "Wann haben wir dich krank gesehen oder im Gefängnis und sind zu dir gekommen?'",
        40: "Und der König wird ihnen antworten: 'Wahrlich, ich sage euch: Jeden Liebesdienst, den ihr einem meiner geringsten Brüder, die hier stehen, erwiesen habt, den habt ihr mir erwiesen.'",
        41: "Dann wird der König sagen zu denen, die ihm zur Linken stehen: 'Hinweg von meinem Angesicht, ihr Verfluchten! Geht in das ewige Feuer, das mein Vater dem Teufel und seinen Engeln bereitet hat!",
        42: 'Denn ich bin hungrig gewesen, und ihr habt mir keine Speise gereicht; ich bin durstig gewesen und ihr habt mich nicht getränkt;',
        43: "ich bin obdachlos gewesen, und ihr habt mich nicht aufgenommen; ich bin nackt gewesen, und ihr habt mich nicht bekleidet; ich bin krank und im Gefängnis gewesen und ihr habt mich nicht besucht!'",
        44: "Dann werden auch sie erwidern: 'Herr, wann haben wir dich hungrig oder durstig gesehen, wann obdachlos oder nackt, wann krank oder im Gefängnis, und haben dir nicht gedient?'",
        45: "Dann wird er ihnen antworten: 'Wahrlich, ich sage euch: Was ihr versäumt habt an einem der Geringsten, die hier stehen, das habt ihr an mir versäumt.'",
        46: 'Und sie gehen weg zu ewiger Strafe; die Gerechten aber gehen ein ins ewige Leben."',
    },
    26: {
        1: 'Als Jesus alle diese Reden vollendet hatte, sprach er zu seinen Jüngern:',
        2: '"Ihr wißt, daß übermorgen das Passahfest ist; dann wird der Menschensohn dem Kreuzestod überliefert."',
        3: 'Da versammelten sich die Hohenpriester und Ältesten des Volkes in dem Palast des Hohenpriesters, namens Kaiphas,',
        4: 'und beratschlagten, wie sie Jesus mit List in ihre Gewalt bekommen und töten könnten.',
        5: 'Sie sagten aber: "Nur nicht am Fest! Es könnte sonst zu einer Volkserhebung kommen."',
        6: 'Als sich nun Jesus in Bethanien im Haus Simons des Aussätzigen aufhielt,',
        7: 'trat eine Frau zu ihm mit einem Glas kostbaren Salböls und goß es auf sein Haupt, während er auf seinem Sitz beim Mahl ruhte.',
        8: 'Bei diesem Anblick wurden die Jünger unwillig und sprachen:',
        9: '"Schade um das Salböl! Man hätte es teuer verkaufen und das Geld den Armen geben können."',
        10: 'Jesus hörte das und sprach zu ihnen: "Warum kränkt ihr die Frau? Sie hat ein rühmlich Werk an mir getan.',
        11: 'Denn Arme habt ihr immer bei euch, mich aber habt ihr nicht immer.',
        12: 'Mit diesem Öl, das sie auf meinen Leib gegossen, hat sie mich zum Begräbnis gesalbt.',
        13: 'Wahrlich, ich sage euch: Wo in der weiten Welt diese meine Heilsbotschaft verkündigt wird, da wird man auch zu ihrem Gedächtnis von ihrer Tat erzählen."',
        14: 'Darauf ging einer der Zwölf, mit Namen Judas, aus Kariot, zu den Hohenpriestern',
        15: 'und sprach: "Was wollt ihr mir geben, wenn ich ihn euch in die Hände liefere?" Sie zahlten ihm dreißig Silberlinge.',
        16: 'Seitdem suchte er nach einer günstigen Gelegenheit, ihn zu verraten.',
        17: 'Am ersten Tag der ungesäuerten Brote traten die Jünger zu Jesus und fragten ihn: "Wo sollen wir das Passahmahl bereiten?"',
        18: 'Er antwortete: "Geht in die Stadt zu dem und dem und sprecht zu ihm: \'Der Meister läßt dir sagen: Meine Zeit ist nahe; bei dir will ich das Passah halten mit meinen Jüngern.\'"',
        19: 'Die Jünger führten Jesu Auftrag aus und richteten die Passahmahlzeit zu.',
        20: 'Als dann der Abend kam, nahm er mit den zwölf Jüngern beim Mahl Platz.',
        21: 'Während sie aßen, sprach er: "Wahrlich, ich sage euch: Einer unter euch wird mich verraten!"',
        22: 'Da wurden sie tief betrübt, und einer nach dem anderen fragte ihn: "Herr, ich bin\'s doch nicht?"',
        23: 'Er erwiderte: "Der eben seine Hand mit mir in die Schüssel getunkt hat, der wird mich verraten.',
        24: 'Der Menschensohn geht zwar zum Tode, das steht ja von ihm geschrieben. Doch weh dem Menschen, durch den der Menschensohn verraten wird! Für diesen Menschen wäre es am besten, er wäre nie geboren."',
        25: 'Da nahm Judas, sein Verräter, das Wort und fragte ihn: "Ich bin\'s doch nicht, Meister?" Er sprach zu ihm: "Du bist es."',
        26: 'Als sie aßen, nahm Jesus das Brot, sprach den Segen, brach\'s und gab es seinen Jüngern mit den Worten: "Nehmt, eßt, das ist mein Leib!"',
        27: 'Darauf nahm er einen Becher, sprach das Dankgebet und reichte ihn den Jüngern mit den Worten:',
        28: '"Trinkt alle daraus! Denn dies ist mein Blut, das Blut des Neuen Bundes, das für viele vergossen werden soll zur Vergebung der Sünden.',
        29: 'Doch ich sage euch: Ich will nie wieder von diesem Gewächs des Weinstocks trinken bis zu dem Tag, wo ich den neuen Wein mit euch trinke in meines Vaters Königreich."',
        30: 'Nach dem Lobgesang gingen sie hinaus an den Ölberg.',
        31: 'Auf dem Weg dorthin sprach Jesus zu ihnen: "In dieser Nacht werdet ihr alle an mir irrewerden. Denn es steht geschrieben: Ich will den Hirten schlagen, und die Schafe der Herde werden sich zerstreuen.',
        32: 'Nach meiner Auferstehung aber will ich euch vorausgehen nach Galiläa."',
        33: 'Petrus sprach zu ihm: "Wenn auch alle anderen an dir irrewerden — ich nun und nimmer!"',
        34: 'Jesus antwortete ihm: "Wahrlich, ich sage dir: In dieser Nacht, noch vor dem Hahnenschrei, wirst du mich dreimal verleugnen."',
        35: 'Petrus entgegnete ihm: "Und müßte ich auch mit dir sterben, ich verleugne dich sicher nicht." Ebenso sprachen auch alle anderen Jünger.',
        36: 'Dann kam Jesus mit seinen Jüngern zu einem Landgut, mit Namen Gethsemane. Und er sprach zu ihnen: "Setzt euch hier nieder, während ich dorthin gehe und bete!"',
        37: 'Er nahm Petrus und die beiden Söhne des Zebedäus mit sich. Nun überfiel ihn Traurigkeit und Grauen,',
        38: 'und er sprach zu ihnen: "Meine Seele ist zum Tode betrübt; bleibt hier und wacht mit mir!"',
        39: 'Dann ging er ein wenig weiter, fiel nieder auf sein Angesicht und betete: "Mein Vater, ist es möglich, so gehe dieser Kelch an mir vorüber. Doch nicht wie ich will, sondern wie du willst."',
        40: 'Und er kam zurück zu seinen Jüngern und fand sie schlafend. Da sprach er zu Petrus: "Könnt ihr denn nicht einmal eine Stunde mit mir wachen?',
        41: 'Wachet und betet, damit ihr nicht in Versuchung fallet! Der Geist ist zwar willig, aber das Fleisch ist schwach."',
        42: 'Dann ging er zum zweiten Mal hin und betete: "Mein Vater, kann dieser Kelch nicht vorübergehen, ohne daß ich ihn trinke, so geschehe dein Wille."',
        43: 'Als er zurückkam fand er sie wieder schlafend; denn die Augen fielen ihnen zu vor Müdigkeit.',
        44: 'Und er verließ sie, ging wieder weg und betete zum dritten Mal, ganz mit denselben Worten.',
        45: 'Dann kam er zu den Jüngern und sprach zu ihnen: "Ihr schlaft noch weiter und ruht? Seht, der Augenblick ist nahe! Jetzt wird der Menschensohn in Sünderhände geliefert!',
        46: 'Auf, wir gehn! Mein Verräter naht!"',
        47: 'Während er noch redete, da erschien Judas, einer der Zwölf, begleitet von einer großen Schar, die, mit Schwertern und Knütteln bewaffnet, von den Hohenpriestern und Ältesten des Volkes ausgesandt war.',
        48: 'Sein Verräter aber hatte ein Zeichen mit ihnen verabredet und gesagt: "Wen ich küsse, der ist\'s, den nehmt fest!"',
        49: 'Sogleich nun trat er auf Jesus zu mit den Worten: "Sei gegrüßt, Meister!" und küßte ihn.',
        50: 'Jesus aber sprach zu ihm: "Freund, wozu bist du hier?" Nun traten sie hinzu, legten Hand an Jesus und nahmen ihn gefangen.',
        51: 'Doch einer der Begleiter Jesu streckte seine Hand aus, zog sein Schwert, schlug nach dem Knecht des Hohenpriesters und hieb ihm das Ohr ab.',
        52: 'Da sprach Jesus zu ihm: "Stecke dein Schwert wieder ein! Denn alle, die zum Schwert greifen, sollen durchs Schwert umkommen.',
        53: 'Oder meinst du, ich könnte meinen Vater nicht bitten, er möge mir in diesem Augenblick mehr als zwölf Heerscharen Engel zu Hilfe senden?',
        54: 'Wie würde dann aber die Schrift erfüllt? Es muß so kommen!"',
        55: 'Zugleich sprach Jesus zu der Schar: "Wie gegen einen Räuber seid ihr mit Schwertern und Knütteln ausgezogen, um mich gefangenzunehmen. Tagtäglich habe ich im Tempel gesessen und gelehrt, und ihr habt mich nicht festgenommen."',
        56: '- Dies alles aber ist geschehen, damit sich die Schriften der Propheten erfüllten. — Da verließen ihn alle seine Jünger und flohen.',
        57: 'Nach seiner Gefangennahme ward Jesus zu dem Hohenpriester Kaiphas geführt, bei dem sich die Schriftgelehrten und Ältesten versammelt hatten.',
        58: 'Petrus aber folgte ihm von weitem bis zu des Hohenpriesters Palast; dort trat er ein und setzte sich zu den Dienern, um zu sehen, wie es ende.',
        59: 'Die Hohenpriester aber und der ganze Hohe Rat suchten nach einem falschen Zeugnis gegen Jesus, damit sie ihm zum Tod verurteilen könnten.',
        60: 'Aber obwohl viele falsche Zeugen auftraten, fanden sie doch keines. Schließlich kamen zwei',
        61: 'und sagten aus: "Dieser Mann hat behauptet: Ich kann den Tempel Gottes niederreißen und ihn in drei Tagen wiederbauen."',
        62: 'Da erhob sich der Hohepriester und sprach zu ihm: "Antwortest du nichts auf das, was diese wider dich vorbringen?"',
        63: 'Doch Jesus schwieg. Dach sprach der Hohepriester zu ihm: "Ich beschwöre dich bei Gott, dem Lebendigen: Sag uns: bist du der Messias, Gottes Sohn?"',
        64: 'Jesus erwiderte: "Ja, ich bin\'s. Doch ich versichere euch: Von nun an sollt ihr den Menschensohn sitzen sehen zur Rechten der Macht und kommen auf des Himmels Wolken."',
        65: 'Da zerriß der Hohepriester seine Kleider und sprach: "Er hat Gott gelästert! Was brauchen wir noch weiter Zeugen? Ihr habt ja selbst seine Gotteslästerung gehört.',
        66: 'Wie urteilt ihr?" Sie erwiderten ihm: "Er ist des Todes schuldig!"',
        67: 'Nun spien sie ihm ins Angesicht und schlugen ihn mit Fäusten; andere gaben ihm Backenstreiche',
        68: 'und sprachen dabei (höhnisch): "Zeig dich als Prophet, Messias! Sag uns: wer hat dich geschlagen?"',
        69: 'Unterdes saß Petrus draußen im Hof. Da kam eine Magd auf ihn zu und sprach: "Du warst auch bei dem Jesus aus Galiläa!"',
        70: 'Er leugnete aber in Gegenwart aller und sagte: "Ich verstehe nicht, was du von mir willst."',
        71: 'Als er dann aus dem inneren Hof in die Halle trat, sah ihn eine andere Magd. Die sprach zu den Leuten dort: "Der hier hat zu Jesus von Nazaret gehört!"',
        72: 'Und wieder leugnete er und schwur dazu: "Ich kenne den Menschen nicht!"',
        73: 'Nach einer kleinen Weile traten die Umstehenden zu Petrus und sprachen: "Wahrhaftig, du gehörst auch zu ihnen! Schon deine Mundart verrät dich."',
        74: 'Da fing er an, sich zu verwünschen und zu schwören: "Ich kenne den Menschen nicht!" In dem Augenblick krähte ein Hahn.',
        75: 'Da dachte Petrus an Jesu Wort: "Noch vor dem Hahnenschrei wirst du mich dreimal verleugnen." Und er ging hinaus und weinte bitterlich.',
    },
    27: {
        1: 'Nach Tagesanbruch berieten alle Hohenpriester und die Ältesten des Volkes, wie sie das Todesurteil an Jesus am besten vollziehen lassen könnten.',
        2: 'Dann führten sie ihn gefesselt ab und überlieferten ihn dem Statthalter Pontius Pilatus.',
        3: 'Als Judas, sein Verräter, sah, daß er verurteilt worden war, da brachte er, von Reue gequält, die dreißig Silberlinge den Hohenpriestern und Ältesten zurück',
        4: 'und sprach: "Ich habe mich versündigt durch den Verrat unschuldigen Bluts."',
        5: 'Sie antworteten ihm: "Was geht uns das an? Das ist deine Sache!" Da warf er das Geld in den Tempel und eilte davon, ging hin und erhängte sich.',
        6: 'Die Hohenpriester aber nahmen das Geld und sprachen: "Es darf nicht in den Tempelschatz gelegt werden, denn es ist Blutgeld."',
        7: 'So kauften sie denn nach einer Beratung den bekannten Töpferacker dafür zum Begräbnisplatz für die Fremden.',
        8: 'Darum heißt der Acker noch heutigentags der Blutacker.',
        9: 'So erfüllte sich das Wort des Propheten Jeremia: Ich nahm die dreißig Silberlinge, die ich als Lohn empfangen für ihn, auf den einige der Söhne Israels einen Preis gesetzt,',
        10: 'und gab sie für den Töpferacker, wie mir der Herr befohlen hatte.',
        11: 'Jesus wurde nun vor den Statthalter geführt. Der fragte ihn: "Bist du der Juden König?" Jesus antwortete: "Ja, ich bin\'s."',
        12: 'Doch auf die Anklagen der Hohenpriester und Ältesten erwiderte er nichts.',
        13: 'Da sprach Pilatus zu ihm: "Hörst du nicht, was sie alles gegen dich vorbringen?"',
        14: 'Aber er antwortete ihm auf keine einzige Frage, so daß es den Statthalter sehr wunder nahm.',
        15: 'Nun pflegte der Statthalter an jedem Passahfest dem Volk nach dessen freier Wahl einen Gefangenen loszugeben.',
        16: 'Man hatte damals aber einen berüchtigten Gefangenen, der hieß Barabbas.',
        17: 'Als sich nun viele aus dem Volk angesammelt hatten, fragte sie Pilatus: "Wen soll ich euch losgeben: Barabbas oder Jesus, den man den Messias nennt?"',
        18: 'Er wußte nämlich, daß sie ihn nur aus Neid überantwortet hatten.',
        19: 'Während er auf dem Richterstuhl saß, ließ seine Frau ihm sagen: "Habe du nichts zu schaffen mit diesem Gerechten; denn ich habe heute nacht einen unheilvollen Traum über ihn gehabt."',
        20: 'Die Hohenpriester und die Ältesten hatten indes das Volk dazu beredet, Barabbas sich loszubitten und Jesu Tod zu fordern.',
        21: 'Als nun der Statthalter sie von neuem fragte: "Wen von diesen beiden soll ich euch losgeben?", da riefen sie: "Barabbas!"',
        22: 'Pilatus sprach zu ihnen: "Was soll ich denn mit Jesus machen, den man den Messias nennt?" Sie riefen alle: "Ans Kreuz mit ihm!"',
        23: 'Da fragte der Statthalter: "Was hat er denn verbrochen?" Sie aber schrien nur noch lauter: "Ans Kreuz mit ihm!"',
        24: 'Als nun Pilatus einsah, daß er nichts erreichte, sondern daß der Lärm immer ärger wurde, da ließ er Wasser bringen, wusch sich vor aller Augen die Hände und sprach: "Ich bin unschuldig an dem Blut dieses Gerechten! Seht ihr zu!"',
        25: 'Da rief das ganze Volk: "Sein Blut komme auf uns und auf unsere Kinder!"',
        26: 'Da gab er ihnen Barabbas los. Jesus aber ließ er geißeln und übergab ihn dann (den Soldaten) zur Kreuzigung.',
        27: 'Nun führten die Soldaten des Statthalters Jesus in das Innere des Palastes und sammelten die ganze Schar ihrer Genossen, um ihren Spott mit ihm zu treiben.',
        28: 'Sie entkleideten ihn, legten ihm einen scharlachroten Soldatenmantel um,',
        29: 'flochten aus Dornen eine Krone und setzten sie ihm aufs Haupt und gaben ihm einen Rohrstab in seine rechte Hand. Dann beugten sie die Knie vor ihm und riefen höhnisch: "Heil dir, Judenkönig!"',
        30: 'Dabei spien sie ihn an, nahmen den Rohrstab und schlugen ihn damit aufs Haupt.',
        31: 'Als sie so ihren Spott mit ihm getrieben hatten, zogen sie ihm den Soldatenmantel aus, legten ihm seine eigenen Kleider wieder an und führten ihn ab zur Kreuzigung.',
        32: 'Als sie die Stadt verließen, trafen sie einen Mann aus Kyrene, namens Simon. Den zwangen sie, Jesu Kreuz zu tragen.',
        33: 'So kamen sie zu einem Platz, namens Golgatha, das heißt Schädelstätte.',
        34: 'Dort gaben sie ihm betäubenden Wein zu trinken. Doch als er ihn gekostet hatte, wollte er ihn nicht trinken.',
        35: 'Nach seiner Kreuzigung verteilten sie seine Kleider unter sich, indem sie das Los darüber warfen.',
        36: 'Dann setzten sie sich dort nieder und hielten bei ihm Wache.',
        37: 'Über seinem Haupt aber war eine Inschrift angebracht mit der Angabe seiner Schuld, die lautete: Dies ist Jesus, der Juden König.',
        38: 'Auch wurden mit ihm zwei Räuber gekreuzigt, der eine zu seiner Rechten, der andere zu seiner Linken.',
        39: 'Die Vorübergehenden aber schmähten ihn: sie schüttelten den Kopf',
        40: 'und sprachen: "Du wolltest ja den Tempel niederreißen und ihn in drei Tagen wiederbauen. Nun hilf dir selbst! Bist du Gottes Sohn, so steige vom Kreuz herab!"',
        41: 'Auch die Hohenpriester samt den Schriftgelehrten und den Ältesten spotteten und sagten:',
        42: '"Anderen hat er geholfen, und sich selbst kann er nun nicht helfen! Er will ja der König Israels sein! Nun gut, so mag er jetzt vom Kreuz heruntersteigen! Dann wollen wir an ihn glauben.',
        43: 'Er hat auf Gott vertraut; der mag ihn nun retten, wenn\'s ihm gefällt. Er hat ja gesagt: ich bin Gottes Sohn."',
        44: 'Ebenso beschimpften ihn die Räuber, die mit ihm gekreuzigt waren.',
        45: 'Von der sechsten Stunde aber bis zur neunten bedeckte Finsternis die ganze Gegend.',
        46: 'Und um die neunte Stunde rief Jesus mit lauter Stimme: "Eli, Eli, lema sabachthani!" Das heißt: Mein Gott, mein Gott, warum hast du mich verlassen?',
        47: 'Als dies einige der Umstehenden hörten, sprachen sie: "Der ruft Elia."',
        48: 'Sofort lief einer von ihnen hin, nahm einen Schwamm, füllte ihn mit Essig, steckte ihn auf einen Rohrstab und wollte ihm zu trinken geben.',
        49: 'Da sprachen die anderen: "Laß doch! Wir wollen sehen, ob Elia wirklich kommt und ihm hilft."',
        50: 'Jesus aber schrie nochmals laut und gab den Geist auf.',
        51: 'In diesem Augenblick zerriß der Tempelvorhang von oben bis unten in zwei Stücke.',
        52: 'Die Erde erbebte. Die Felsen zerbarsten. Die Gräber öffneten sich, und viele Leiber der entschlafenen Heiligen wurden auferweckt;',
        53: 'die gingen aus ihren Gräbern hervor, kamen nach seiner Auferstehung in die heilige Stadt und erschienen vielen.',
        54: 'Als aber der Hauptmann und seine Leute, die bei Jesus Wache hielten, das Erdbeben und, was sich sonst noch zutrug, sahen, da wurden sie von großer Furcht erfüllt und sprachen: "Dieser Mann ist wirklich Gottes Sohn gewesen!"',
        55: 'Es waren dort auch viele Frauen, die von fern zusahen: sie hatten Jesus von Galiläa her begleitet und ihm gedient.',
        56: 'Unter ihnen waren auch Maria aus Magdala, Maria, die Mutter des Jakobus und des Josef, und die Mutter der Söhne des Zebedäus.',
        57: 'Am Abend kam ein reicher Mann, aus Arimathäa gebürtig, mit Namen Josef, der auch eine Jünger Jesu geworden war.',
        58: 'Der ging zu Pilatus und bat ihn um Jesu Leichnam. Da befahl Pilatus, man solle ihm den Leichnam überlassen.',
        59: 'Nun nahm Josef den Leichnam, ließ ihn in reine Leinwand wickeln',
        60: 'und in ein noch unbenutztes Grab legen, da er für sich in einen Felsen hatte hauen lassen. Dann ließ er einen großen Stein vor die Grabesöffnung wälzen und entfernte sich.',
        61: 'Maria aus Magdala aber und die andere Maria blieben dort und setzten sich dem Grab gegenüber.',
        62: 'Am nächsten Tag, am Tag nach dem Freitag, kamen die Hohenpriester und die Pharisäer gemeinsam zu Pilatus',
        63: 'und sprachen: "Herr, es ist uns eingefallen, daß jener Betrüger bei seinen Lebzeiten gesagt hat: \'Nach drei Tagen werde ich auferstehen.\'',
        64: 'Laß nun das Grab bis zum dritten Tag streng bewachen, damit nicht etwa seine Jünger kommen und ihn stehlen und dann zum Volk sagen: \'Er ist von den Toten auferstanden.\' Dann wäre der letzte Betrug noch schlimmer als der erste."',
        65: 'Pilatus sprach zu ihnen: "Ihr sollt eine Wache haben. Geht hin und verwahrt das Grab, so gut ihr könnt."',
        66: 'Da gingen sie hin und sicherten das Grab: sie versiegelten den Stein und stellten die Wache aus.',
    },
    28: {
        1: 'Nach dem Sabbat, im Morgengrauen des ersten Wochentages, gingen Maria von Magdala und die andere Maria hin, um das Grab zu besuchen.',
        2: 'Plötzlich entstand ein starkes Erdbeben. Denn ein Engel des Herrn kam vom Himmel herab, trat zum Grab, wälzte den Stein hinweg und setzte sich darauf.',
        3: 'Er sah aus wie ein leuchtender Blitz, und sein Gewand war weiß wie Schnee.',
        4: 'Bei seinem Anblick erschraken die Grabeswächter: sie erbebten und waren wie tot.',
        5: 'Der Engel aber sprach zu den Frauen: "Fürchtet ihr euch nicht! Ich weiß, ihr wollt nach Jesus sehen, dem Gekreuzigten.',
        6: 'Er ist nicht hier, er ist auferstanden, wie er es vorausgesagt. Kommt her und seht die Stätte, wo er gelegen hat!',
        7: 'Geht jetzt schnell hin und meldet seinen Jüngern: \'Er ist auferstanden von den Toten und geht euch nun voraus nach Galiläa; dort werdet ihr ihn sehen!\' Das versichere ich euch."',
        8: 'Da gingen sie schnell von dem Grab weg, und noch voll Schrecken, aber auch in großer Freude eilten sie davon, um seinen Jüngern, diese Botschaft zu bringen.',
        9: 'Plötzlich trat ihnen Jesus entgegen mit den Worten: "Seid gegrüßt!" Da eilten sie auf ihn zu, umfaßten seine Füße und fielen vor ihm nieder.',
        10: 'Jesus aber sprach zu ihnen: "Fürchtet euch nicht! Geht hin und sagt meinen Brüdern, sie sollen nach Galiläa gehen: dort werden sie mich sehen.!',
        11: 'Während sie ihres Weges gingen, kamen einige der Grabeswächter in die Stadt und meldeten den Hohenpriestern alles, was vorgefallen war.',
        12: 'Da hielten diese mit den Ältesten eine Versammlung und, als sie Rats gepflogen, gaben sie den Soldaten reichlich Geld',
        13: 'und sprachen: "Sagt: \'Seine Jünger sind bei Nacht gekommen und haben ihn gestohlen, als wir gerade schliefen.\'',
        14: 'Und wenn es dem Statthalter zu Ohren kommt, so wollen wir ihn schon beschwichtigen und dafür sorgen, daß ihr straflos ausgeht."',
        15: 'Da nahmen sie das Geld und taten, wie sie angewiesen waren. So hat sich dies Gerede bei den Juden verbreitet, und noch heute ist es in Umlauf.',
        16: 'Die elf Jünger aber gingen nach Galiläa auf den Berg, wohin sie Jesus beschieden hatte.',
        17: 'Bei seinem Anblick fielen sie anbetend vor ihm nieder; andere aber hatten Zweifel.',
        18: 'Da trat Jesus näher und sprach zu ihnen: "Mir ist alle Macht verliehen worden im Himmel und auf Erden.',
        19: 'So geht denn hin und sammelt mir aus allen Völkern Jünger: führt sie durch die Taufe in die Gemeinschaft des Vaters, des Sohnes und des Heiligen Geistes',
        20: 'und lehrt sie gehorchen allem, was ich euch geboten habe. Und wisset: ich bin bei euch alle Tage bis an das Ende dieser Weltzeit."',
    },
}
